fn summary_request(task: &str, path: &str, text: &str) -> String {
    let words: Vec<&str> = task
        .split_whitespace()
        .filter(|word| !word.contains(path))
        .collect();
    let request = words.join(" ");
    format!("{}: {}", request.trim_end_matches(CLAUSE_ENDS), text.trim())
}

