    toks: &[Token<'_>],
    binding: &WriteBinding,
) -> Option<(String, String)> {
    let lowered = request.to_lowercase();
    let dest_cues = bare_surfaces(seed::ROLE_FILE_WRITE_DESTINATION_CUE);
    let file_index = binding.index;
    let target = binding.path.clone();
