        .role_word_forms(seed::ROLE_FILE_WRITE_DEFERRED_CONTENT_REFERENCE)
        .iter()
        .any(|form| match form.slot() {
            Slot::Bare => lower == form.text,
            Slot::Suffix => ends_with_head_noun(&lower, form.after_slot().trim_start()),
