};

#[derive(Debug, Clone, PartialEq, Eq)]
struct GroundedRewrite {
    target: String,
    pattern: String,
    replacement: String,
    /// How the pattern is allowed to match. Renaming an identifier is a
    /// word-scoped edit; replacing a quoted literal is a substring one -- or a
    /// word-scoped one when the new word contains the old (`smal` → `small`).
    scope: RewriteScope,
    /// Whether the request renamed a name (a word-scoped rename).
    renaming: bool,
    /// Whether the pattern must occur exactly once (a positional insertion's
    /// anchor), replaced once rather than everywhere.
    unique: bool,
    /// Whether the replacement holds the pattern, so it is applied in one
    /// pass rather than rewritten until no pattern is left (PR #1188 G78).
    single_pass: bool,
    /// The seed sentence that states the change, when it is not the
    /// rename/replace one (a positional insertion's).
    stated: Option<(&'static str, Vec<(&'static str, String)>)>,
    /// The pattern and replacement as the request wrote them, when it wrote
    /// `\n` / `\t` escapes the rewrite unescaped (see [`as_written`]).
    verbatim: Option<(String, String)>,
}

/// The template slots the seed sentences that state a rewrite fill.
const OLD_SLOT: &str = concat!("{", "old", "}");
const NEW_SLOT: &str = concat!("{", "new", "}");
const ANCHOR_SLOT: &str = concat!("{", "anchor", "}");

impl GroundedRewrite {
    /// The intent whose seed sentence states this change rather than merely
    /// reporting that the file was touched.
    const fn stated_intent(&self) -> &'static str {
        match self.stated {
            Some((intent, _)) => intent,
            None if self.renaming => "coding_identifier_renamed",
            None => "coding_text_replaced",
        }
    }

    /// The operands the seed sentence names, as template slots.
    fn stated_slots(&self) -> Vec<(&str, &str)> {
        match &self.stated {
            Some((_, slots)) => slots
                .iter()
                .map(|(slot, value)| (*slot, value.as_str()))
                .collect(),
            None => vec![
                (OLD_SLOT, self.pattern.as_str()),
                (NEW_SLOT, self.replacement.as_str()),
            ],
        }
    }
}

/// A change whose bytes are settled, awaiting the observation that confirms it.
///
/// `expected` is what the workspace should now hold; `intent` and `slots` are
/// the seed sentence that states the change once it does.
pub(super) struct VerifiedChange<'a> {
    pub(super) target: &'a str,
    pub(super) expected: &'a str,
    pub(super) intent: &'a str,
    pub(super) slots: &'a [(&'a str, &'a str)],
    pub(super) list_slots: &'a [(&'a str, &'a [String])],
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct CompositeModuleChange {
    source_path: String,
    source: String,
    registration_path: String,
    registration: String,
}

pub(super) fn plan_workspace_change_step(
    task: &str,
    messages: &[ChatMessage],
    tool_names: &[&str],
    result: &mut Option<FinalResult>,
) -> Option<AgenticPlan> {
    let task = unwrap_transport_quotes(task);
    // A continuation cue resumes this run rather than opening a new request,
    // so the read and write evidence gathered for it must survive the ping
    // (issue #1138): slicing at the last user message -- the cue itself --
    // restarted the read--write pair on every ping.
    let current_turn = &messages[super::planner::evidence_window_start(messages)..];
    // `Append the contents of a.txt to b.txt`: the source is read, and the
    // request is restated with its lines as the block placed (PR #1188 G50).
    let sourced = match sourced_request(task, current_turn) {
        Some(Sourced::Read(path)) => {
            let tool = tool_for(tool_names, Capability::Read)?;
            return Some(plan_one(tool, read_arguments(&path)));
        }
        Some(Sourced::Task(sourced)) => Some(sourced),
        None => None,
    };
    let task = sourced.as_deref().unwrap_or(task);

    if let Some(change) = composite_module_change(task) {
        return plan_composite_step(task, current_turn, tool_names, &change, result);
    }
    // Numbered lines moved to another file: placed there, then removed (G85).
    if let Some(order) = super::line_range_move::line_range_move(task) {
        return super::line_range_move::plan_line_range_move_step(
            task,
            current_turn,
            tool_names,
            &order,
         result,);
    }
    if let Some(change) = super::workspace_computed_change::grounded_line_change(task) {
        return super::workspace_computed_change::plan_computed_change_step(
            task,
            current_turn,
            tool_names,
            &change,
         result,);
    }
    if let Some(inserts) = insert_sequence(task) {
        return super::positional_edit::plan_insert_sequence_step(
            task,
            current_turn,
            tool_names,
            &inserts,
         result,);
    }
    // Several replacements asked in one sentence are made in order (G82).
    if let Some(change) = super::workspace_computed_change::grounded_replace_list(task) {
        return super::workspace_computed_change::plan_computed_change_step(
            task,
            current_turn,
            tool_names,
            &change,
         result,);
    }
    if let Some(rewrite) = grounded_rewrite(task) {
        return plan_rewrite_step(task, current_turn, tool_names, &rewrite, result);
    }
    let change = super::workspace_computed_change::grounded_computed_change(task)?;
    super::workspace_computed_change::plan_computed_change_step(
        task,
        current_turn,
        tool_names,
        &change,
     result,)
}

/// A request whose additive edit places another file's contents: the source
/// to read first, or the request restated with its lines.
enum Sourced {
    Read(String),
    Task(String),
}

/// `None` unless the request names a contents source and, restated, is an
/// additive edit the composers place.
fn sourced_request(task: &str, current_turn: &[ChatMessage]) -> Option<Sourced> {
    use super::contents_source::{contents_source, with_contents};
    let source = contents_source(task)?;
    let probe = with_contents(task, &source, "x");
    if insert_sequence(&probe).is_none()
        && super::workspace_computed_change::grounded_end_insertion(&probe).is_none()
    {
        return None;
    }
    let Some(read) = result_for_path(current_turn, Capability::Read, &source.path, None) else {
        return Some(Sourced::Read(source.path));
    };
    if super::code_artifact::source_from_agent_read_result(&read).is_none()
        && super::tool_result::failure_message(&read, false, true).is_some()
    {
        return None;
    }
    let contents = source_from_read_result(&read);
    Some(Sourced::Task(with_contents(task, &source, &contents)))
}

fn plan_rewrite_step(
    task: &str,
    current_turn: &[ChatMessage],
    tool_names: &[&str],
    rewrite: &GroundedRewrite,
    result: &mut Option<FinalResult>,
) -> Option<AgenticPlan> {
    let Some(read) = result_for_path(current_turn, Capability::Read, &rewrite.target, None) else {
        let tool = tool_for(tool_names, Capability::Read)?;
        return Some(plan_one(tool, read_arguments(&rewrite.target)));
    };
    let source = source_from_read_result(&read);
    let written = as_written(&source, rewrite);
    let rewrite = written.as_ref().unwrap_or(rewrite);
    let Some(updated) = rewritten_source(&source, rewrite) else {
        // A replace asked again finds its old text gone: that is the answer (G87).
        let absent = super::replace_list::absent_text_answer(
            task,
            &rewrite.target,
            &source,
            &rewrite.pattern,
            Some(&rewrite.replacement),
        );
        return Some(AgenticPlan::Final(match absent {
            Some(answer) => answer,
            None => render_seeded_outcome(
                "coding_workspace_verification_failed",
                task,
                &rewrite.target,
            )?,
        }));
    };

    let occurrences = match rewrite.scope {
        RewriteScope::Substring => source.match_indices(&rewrite.pattern).count(),
        RewriteScope::Word => word_scoped_matches(&source, &rewrite.pattern).len(),
    };
    if occurrences > 1
        && let Some(answer) = super::edit_scope::scoped_decline(task, &rewrite.target, &source)
    {
        return Some(AgenticPlan::Final(answer));
    }
    if occurrences == 1 {
        // The bare pattern when it is unique in the file; otherwise the
        // smallest unique run of changed lines -- the edit tool refuses an
        // `oldString` it finds twice, and `smal` also sits inside `small`.
        let edit = if rewrite.unique {
            anchored_lines(&source, rewrite).map(|(_, old, new)| (old, new))
        } else if source.matches(rewrite.pattern.as_str()).count() == 1 {
            Some((rewrite.pattern.clone(), rewrite.replacement.clone()))
        } else {
            changed_lines_edit(&source, &updated)
        };
        if let Some(tool) = tool_for(tool_names, Capability::Edit)
            && let Some((old, new)) = edit
        {
            if result_for_edit(current_turn, &rewrite.target, &old, &new).is_none() {
                return Some(plan_one(tool, edit_arguments(&rewrite.target, &old, &new)));
            }
            return plan_digest_verification(
                task,
                current_turn,
                tool_names,
                &VerifiedChange {
                    target: &rewrite.target,
                    expected: &updated,
                    intent: rewrite.stated_intent(),
                    slots: &rewrite.stated_slots(),
                    list_slots: &[],
                },
             result,);
        }
    } else if tool_for(tool_names, Capability::Edit).is_some()
        && let Some(command) = repeated_identifier_rewrite_command(rewrite)
        && let Some(tool) = tool_for(tool_names, Capability::Run)
    {
        if result_for_command(current_turn, &command).is_none() {
            return Some(plan_one(tool, json!({"command": command}).to_string()));
        }
        return plan_digest_verification(
            task,
            current_turn,
            tool_names,
            &VerifiedChange {
                target: &rewrite.target,
                expected: &updated,
                intent: rewrite.stated_intent(),
                slots: &rewrite.stated_slots(),
                list_slots: &[],
            },
         result,);
    }

    if result_for_path(
        current_turn,
        Capability::Write,
        &rewrite.target,
        Some(&updated),
    )
    .is_none()
    {
        let tool = tool_for(tool_names, Capability::Write)?;
        return Some(plan_one(tool, write_arguments(&rewrite.target, &updated)));
    }
    let command = format!("cat {}", rewrite.target);
    let Some(observed) = result_for_command(current_turn, &command) else {
        let tool = tool_for(tool_names, Capability::Run)?;
        return Some(plan_one(tool, json!({"command": command}).to_string()));
    };
    if observed != updated {
        return Some(AgenticPlan::Final(render_seeded_outcome(
            "coding_workspace_verification_failed",
            task,
            &rewrite.target,
        )?));
    }
    Some(record(AgenticPlan::Final(render_seeded_change(
        rewrite.stated_intent(),
        task,
        &rewrite.target,
        &rewrite.stated_slots(),
    )?), FinalDisposition::Finding, "workspace_change_observed", result))
}

fn plan_composite_step(
    task: &str,
    current_turn: &[ChatMessage],
    tool_names: &[&str],
    change: &CompositeModuleChange,
    result: &mut Option<FinalResult>,
) -> Option<AgenticPlan> {
    if result_for_path(
        current_turn,
        Capability::Write,
        &change.source_path,
        Some(&change.source),
    )
    .is_none()
    {
        let tool = tool_for(tool_names, Capability::Write)?;
        return Some(plan_one(
            tool,
            write_arguments(&change.source_path, &change.source),
        ));
    }

    let source_command = format!("cat {}", change.source_path);
    let Some(observed_source) = result_for_command(current_turn, &source_command) else {
        let tool = tool_for(tool_names, Capability::Run)?;
        return Some(plan_one(
            tool,
            json!({"command": source_command}).to_string(),
        ));
    };
    if observed_source != change.source {
        return Some(AgenticPlan::Final(render_seeded_outcome(
            "coding_workspace_verification_failed",
            task,
            &change.source_path,
        )?));
    }

    let Some(read) = result_for_path(
        current_turn,
        Capability::Read,
        &change.registration_path,
        None,
    ) else {
        let tool = tool_for(tool_names, Capability::Read)?;
        return Some(plan_one(tool, read_arguments(&change.registration_path)));
    };
    let current = source_from_read_result(&read);
    let updated = insert_registration(&current, &change.registration);
    let registered = ["`", change.registration.trim(), "`"].concat();
    if updated == current {
        return Some(record(AgenticPlan::Final(render_seeded_change(
            "coding_member_already_present",
            task,
            &change.registration_path,
            &[("{members}", &registered)],
        )?), FinalDisposition::Finding, "workspace_change_observed", result));
    }

    if let Some((old, new)) = compact_registration_edit(&current, &change.registration)
        && let Some(tool) = tool_for(tool_names, Capability::Edit)
    {
        if result_for_edit(current_turn, &change.registration_path, &old, &new).is_none() {
            return Some(plan_one(
                tool,
                edit_arguments(&change.registration_path, &old, &new),
            ));
        }
        return plan_digest_verification(
            task,
            current_turn,
            tool_names,
            &VerifiedChange {
                target: &change.registration_path,
                expected: &updated,
                intent: "coding_member_inserted",
                slots: &[("{members}", &registered)],
                list_slots: &[],
            },
         result,);
    }

    if result_for_path(
        current_turn,
        Capability::Write,
        &change.registration_path,
        Some(&updated),
    )
    .is_none()
    {
        let tool = tool_for(tool_names, Capability::Write)?;
        return Some(plan_one(
            tool,
            write_arguments(&change.registration_path, &updated),
        ));
    }

    let registration_command = format!("cat {}", change.registration_path);
    let Some(observed_registration) = result_for_command(current_turn, &registration_command)
    else {
        let tool = tool_for(tool_names, Capability::Run)?;
        return Some(plan_one(
            tool,
            json!({"command": registration_command}).to_string(),
        ));
    };
    if observed_registration != updated {
        return Some(AgenticPlan::Final(render_seeded_outcome(
            "coding_workspace_verification_failed",
            task,
            &change.registration_path,
        )?));
    }
    Some(record(AgenticPlan::Final(render_seeded_change(
        "coding_member_inserted",
        task,
        &change.registration_path,
        &[("{members}", &registered)],
    )?), FinalDisposition::Finding, "workspace_change_observed", result))
}

/// The file after `rewrite`, or `None` when it cannot apply. A positional
/// insertion replaces its one anchor occurrence; an anchor found zero or
/// several times does not say where the line goes.
/// The rewrite as the request wrote it, when the file holds no unescaped
/// pattern but holds the pattern as written (source code quoting `'\n'`,
/// PR #1188 G65).
fn as_written(source: &str, rewrite: &GroundedRewrite) -> Option<GroundedRewrite> {
    let (pattern, replacement) = rewrite.verbatim.clone()?;
    if (rewrite.pattern != pattern && source.contains(&rewrite.pattern))
        || !source.contains(&pattern)
    {
        return None;
    }
    Some(GroundedRewrite {
        pattern,
        replacement,
        verbatim: None,
        ..rewrite.clone()
    })
}

fn rewritten_source(source: &str, rewrite: &GroundedRewrite) -> Option<String> {
    if rewrite.single_pass {
        return source
            .contains(rewrite.pattern.as_str())
            .then(|| source.replace(rewrite.pattern.as_str(), &rewrite.replacement));
    }
    if rewrite.unique {
        let (start, old, new) = anchored_lines(source, rewrite)?;
        return Some([&source[..start], new.as_str(), &source[start + old.len()..]].concat());
    }
    execute_scoped_workspace_rewrite(
        source,
        &rewrite.pattern,
        &rewrite.replacement,
        rewrite.scope,
    )
    .ok()
    .map(|execution| execution.output)
}

/// A positional insertion's one anchor occurrence widened to the whole lines
/// it sits on, as `(start, old_lines, new_lines)`, or `None` unless the anchor
/// occurs exactly once. The inserted text is a line, so an anchor that is only
/// part of a line (`after the line containing '| T20 |'`) must not split it.
fn anchored_lines(source: &str, rewrite: &GroundedRewrite) -> Option<(usize, String, String)> {
    let (pattern, replacement) = (rewrite.pattern.as_str(), rewrite.replacement.as_str());
    let mut found = source.match_indices(pattern).map(|(at, _)| at);
    let (Some(at), None) = (found.next(), found.next()) else {
        return None;
    };
    let start = source[..at].rfind('\n').map_or(0, |newline| newline + 1);
    let tail = at + pattern.len();
    let end = if pattern.ends_with('\n') {
        tail - 1
    } else {
        source[tail..]
            .find('\n')
            .map_or(source.len(), |newline| tail + newline)
    };
    let old = &source[start..end];
    let new = replacement.strip_prefix(pattern).map_or_else(
        || [&replacement[..replacement.len() - pattern.len()], old].concat(),
        |rest| [old, rest].concat(),
    );
    Some((start, old.to_owned(), new))
}

/// The smallest run of whole lines holding every change from `source` to
/// `updated`, as an edit pair, when that run occurs once in `source`.
pub(super) fn changed_lines_edit(source: &str, updated: &str) -> Option<(String, String)> {
    const MAX_EDIT_BYTES: usize = 4096;
    let prefix = source
        .bytes()
        .zip(updated.bytes())
        .take_while(|(left, right)| left == right)
        .count();
    let limit = source.len().min(updated.len()) - prefix;
    let suffix = source
        .bytes()
        .rev()
        .zip(updated.bytes().rev())
        .take(limit)
        .take_while(|(left, right)| left == right)
        .count();
    // Byte positions only meet `\n`, so `start` and `end` fall on line -- and
    // therefore character -- boundaries even when the first or last differing
    // byte sits inside a multi-byte character.
    let bytes = source.as_bytes();
    let line_start = |before: usize| {
        bytes[..before]
            .iter()
            .rposition(|byte| *byte == b'\n')
            .map_or(0, |at| at + 1)
    };
    let mut start = line_start(prefix);
    let end = bytes[source.len() - suffix..]
        .iter()
        .position(|byte| *byte == b'\n')
        .map_or(source.len(), |at| source.len() - suffix + at);
    // Lines inserted between two lines change none: the line above carries
    // them.
    if start == end && start > 0 {
        start = line_start(start - 1);
    }
    let old = &source[start..end];
    let new = &updated[start..updated.len() - (source.len() - end)];
    (!old.is_empty() && old.len() <= MAX_EDIT_BYTES && source.matches(old).count() == 1)
        .then(|| (old.to_owned(), new.to_owned()))
}

/// `Insert 'x' after the line 'y' in f`: the anchor line, replaced once by the
/// anchor beside the new line, stated by the position meaning that placed it.
fn grounded_positional_insert(task: &str) -> Option<GroundedRewrite> {
    let (target, anchor, replacement) = super::positional_edit::compose_positional_insert(task)?;
    let after_anchor = [anchor.as_str(), "\n"].concat();
    let (after, inserted) = if let Some(inserted) = replacement.strip_prefix(&after_anchor) {
        (true, inserted.to_owned())
    } else {
        let before_anchor = ["\n", anchor.as_str()].concat();
        (false, replacement.strip_suffix(&before_anchor)?.to_owned())
    };
    let intent = super::positional_edit::insert_intent(after, &inserted);
    Some(GroundedRewrite {
        target,
        stated: Some((
            intent,
            vec![(NEW_SLOT, inserted), (ANCHOR_SLOT, anchor.clone())],
        )),
        pattern: anchor,
        replacement,
        scope: RewriteScope::Substring,
        renaming: false,
        unique: true,
        single_pass: false,
        verbatim: None,
    })
}

/// Every insert the request asks for, each its own anchored edit.
///
/// Several clauses (`…, and insert …`), an anchor named by the line it
/// follows (T31, T34), lines rebased on the anchor (G16), or one insert whose
/// anchor is a whole line also found inside others (`the line 'b'`).
fn insert_sequence(task: &str) -> Option<Vec<PositionalInsert>> {
    super::positional_edit::positional_inserts(task)
}

fn grounded_rewrite(task: &str) -> Option<GroundedRewrite> {
    if let Some(positional) = grounded_positional_insert(task) {
        return Some(positional);
    }
    let (target, old_clause, new_clause) = compose_edit_request(task)?;
    let renaming = seed::lexicon().mentions_role(
        seed::ROLE_CODING_IDENTIFIER_RENAME_ACTION,
        &task.to_lowercase(),
    );
    // A request that names a line replaces whole lines
    // (`grounded_line_replacement`).
    if !renaming && super::workspace_computed_change::names_line(task) {
        return None;
    }
    // Both operands have to be literals the request actually quoted, so prose
    // ("replace the old header with something clearer") is never rewritten as
    // bytes. What that cannot be is a count: requiring the request to hold
    // *exactly* two quoted segments made every other pair of delimiters in the
    // prompt disqualify the edit, and this repository's own prose backticks the
    // file it names. The issue #1028 ladder node "In the file
    // `src/protocol_memory.rs`, replace \"request_history\" with
    // \"conversation_history\"" quotes three things and states one replacement.
    // Asking whether each clause *is* quoted keeps the guarantee and drops the
    // arithmetic.
    // The edit request unescapes `\n` / `\t` in its literals, so the quoted
    // segments are compared unescaped too: a multi-line replacement written
    // with `\n` was otherwise not "quoted", and the general fallback wrote its
    // new text over the whole file (PR #1188 sub-agent gap 3).
    let quoted: Vec<String> = quoted_segments(task)
        .iter()
        .map(String::as_str)
        .map(super::positional_edit::unescape_prose_newlines)
        .collect();
    // A literal quoted whole counts even when backtick spans inside it pair
    // among themselves (PR #1188 G63).
    let is_quoted =
        |value: &String| quoted.contains(value) || crate::normal_markov::quotes_whole(task, value);
    let operands = if is_quoted(&old_clause) && is_quoted(&new_clause) {
        Some((old_clause, new_clause))
    } else if renaming {
        Some((
            identifier_tokens(&old_clause).next_back()?.to_owned(),
            identifier_tokens(&new_clause).next()?.to_owned(),
        ))
    } else {
        None
    }?;
    let (old, new) = operands;
    let as_quoted = |text: &str| {
        quoted_segments(task)
            .into_iter()
            .find(|raw| raw != text && super::positional_edit::unescape_prose_newlines(raw) == text)
            .unwrap_or_else(|| text.to_owned())
    };
    let verbatim = (as_quoted(&old) != old || as_quoted(&new) != new)
        .then(|| (as_quoted(&old), as_quoted(&new)));
    // A rename names a *word*, so the edit is word-scoped whichever way the
    // request spelled its operands. Without that scope the most ordinary rename
    // there is -- giving a name a prefix or a suffix -- has to be refused, since
    // an unanchored substring rewrite that reintroduces its own pattern never
    // terminates.
    //
    // A word replaced by a longer word that contains it (`smal` → `small`, a
    // typo fix) is only safe word by word for the same reason.
    let words = is_identifier_word(&old) && is_identifier_word(&new);
    let scope = if words && (renaming || new.contains(&old)) {
        RewriteScope::Word
    } else {
        RewriteScope::Substring
    };
    if old.is_empty() || old == new {
        return None;
    }
    // A new text holding the old one (`key 3` → `key 33`) is replaced in one
    // pass over the file, never rewritten again inside its own result (PR
    // #1188 G78).
    let single_pass = scope == RewriteScope::Substring && new.contains(&old);
    Some(GroundedRewrite {
        target,
        pattern: old,
        replacement: new,
        scope,
        renaming: renaming && scope == RewriteScope::Word,
        unique: false,
        single_pass,
        stated: None,
        verbatim,
    })
}

// This is a seed-template placeholder, not a Rust formatting argument.
#[allow(clippy::literal_string_with_formatting_args)]
fn composite_module_change(task: &str) -> Option<CompositeModuleChange> {
    let lowered = task.to_lowercase();
    if !seed::lexicon().mentions_role(seed::ROLE_CODING_MODULE_REGISTRATION_ACTION, &lowered) {
        return None;
    }
    let generated = rust_source_for_task(task)?;
    let registration_path = rust_paths(task)
        .into_iter()
        .find(|path| path != &generated.path)?;
    let module = generated.path.rsplit('/').next()?.strip_suffix(".rs")?;
    if !valid_identifier(module) {
        return None;
    }
    let registration =
        render_rust_template("coding_source_module_registration", &[("{module}", module)])?;
    Some(CompositeModuleChange {
        source_path: generated.path,
        source: generated.content,
        registration_path,
        registration,
    })
}

fn insert_registration(source: &str, registration: &str) -> String {
    if source
        .lines()
        .any(|line| line.trim() == registration.trim())
    {
        return source.to_owned();
    }
    let mut updated = source.to_owned();
    if !updated.is_empty() && !updated.ends_with('\n') {
        updated.push('\n');
    }
    updated.push_str(registration);
    updated
}

fn compact_registration_edit(source: &str, registration: &str) -> Option<(String, String)> {
    const MAX_SUFFIX_BYTES: usize = 4096;
    let mut starts = source
        .match_indices('\n')
        .map(|(index, _)| index + 1)
        .filter(|start| *start < source.len())
        .collect::<Vec<_>>();
    starts.insert(0, 0);
    for start in starts.into_iter().rev() {
        let suffix = &source[start..];
        if suffix.len() > MAX_SUFFIX_BYTES {
            break;
        }
        if source.match_indices(suffix).count() != 1 {
            continue;
        }
        let mut replacement = suffix.to_owned();
        if !replacement.ends_with('\n') {
            replacement.push('\n');
        }
        replacement.push_str(registration);
        return Some((suffix.to_owned(), replacement));
    }
    None
}

fn repeated_identifier_rewrite_command(rewrite: &GroundedRewrite) -> Option<String> {
    if !shell_safe_identifier(&rewrite.pattern) || !shell_safe_identifier(&rewrite.replacement) {
        return None;
    }
    // The in-memory execution and the command the client runs have to agree on
    // what a match is, so a word-scoped rewrite asks for whole words too.
    let pattern = match rewrite.scope {
        RewriteScope::Substring => rewrite.pattern.clone(),
        RewriteScope::Word => format!("\\b{}\\b", rewrite.pattern),
    };
    // `perl -pi -e`, not `sed -i` (issue #1110). GNU and BSD sed disagree about
    // both halves of that command: BSD `-i` reads the script as its backup
    // suffix, and BSD sed has no `\b`. On macOS every rename therefore failed
    // with `bad flag in substitute command`, the file was left unchanged, and
    // Formal AI reported the mismatch as its own verification failure -- a
    // confident failure report instead of a rename. perl's `-pi -e` and `\b`
    // mean the same thing on both, and perl ships with macOS and the runners.
    // Both identifiers are `[A-Za-z0-9_]` by `shell_safe_identifier`, so
    // neither side can carry a regex or shell metacharacter.
    // Assembled from named parts rather than one template string: the prose
    // detector reads `perl -pi -e ...` as a multi-word phrase (two alphabetic
    // runs, one of three letters) and would have it live in `data/seed`, which
    // is the wrong home for a shell invocation. Naming the pieces says what
    // each is, and none of them reads as a sentence.
    let script = format!("'s/{pattern}/{}/g'", rewrite.replacement);
    Some(["perl", "-pi", "-e", &script, "--", &rewrite.target].join(" "))
}

fn shell_safe_identifier(identifier: &str) -> bool {
    !identifier.is_empty()
        && identifier
            .chars()
            .all(|character| character.is_ascii_alphanumeric() || character == '_')
}

pub(super) fn identifier_tokens(text: &str) -> impl DoubleEndedIterator<Item = &str> {
    text.split(|character: char| !character.is_ascii_alphanumeric() && character != '_')
        .filter(|token| valid_identifier(token))
}

fn valid_identifier(identifier: &str) -> bool {
    let mut characters = identifier.chars();
    characters
        .next()
        .is_some_and(|first| first.is_ascii_alphabetic() || first == '_')
        && characters.all(|character| character.is_ascii_alphanumeric() || character == '_')
        && !seed::lexicon()
            .words_for_role(seed::ROLE_IDENTIFIER_RESERVED_WORD)
            .iter()
            .any(|reserved| reserved == identifier)
}

fn rust_paths(task: &str) -> Vec<String> {
    let mut paths = Vec::new();
    for (suffix, _) in task.match_indices(".rs") {
        let end = suffix + 3;
        let start = task[..end]
            .char_indices()
            .rev()
            .take_while(|(_, character)| {
                character.is_ascii_alphanumeric() || matches!(character, '_' | '-' | '.' | '/')
            })
            .last()
            .map_or(0, |(index, _)| index);
        let path = &task[start..end];
        if !path.is_empty()
            && !path.starts_with('/')
            && !path.split('/').any(|component| component == "..")
            && !paths.iter().any(|existing| existing == path)
        {
            paths.push(path.to_owned());
        }
    }
    paths
}

pub(super) fn result_for_path(
    messages: &[ChatMessage],
    capability: Capability,
    path: &str,
    expected_content: Option<&str>,
) -> Option<String> {
    matching_result(messages, |name, arguments| {
        if tool_capability(name) != Some(capability) {
            return false;
        }
        let Ok(value) = serde_json::from_str::<Value>(arguments) else {
            return false;
        };
        let matches_path = ["path", "filePath", "file_path"].iter().any(|key| {
            value
                .get(key)
                .and_then(Value::as_str)
                .is_some_and(|observed| workspace_path_matches(path, observed))
        });
        matches_path
            && expected_content.is_none_or(|expected| {
                value.get("content").and_then(Value::as_str) == Some(expected)
            })
    })
}

pub(super) fn result_for_edit(
    messages: &[ChatMessage],
    path: &str,
    old: &str,
    new: &str,
) -> Option<String> {
    matching_result(messages, |name, arguments| {
        if tool_capability(name) != Some(Capability::Edit) {
            return false;
        }
        let Ok(value) = serde_json::from_str::<Value>(arguments) else {
            return false;
        };
        argument_matches_path(&value, path)
            && argument_matches(&value, &["oldString", "old_string", "old_str", "old"], old)
            && argument_matches(&value, &["newString", "new_string", "new_str", "new"], new)
    })
}

fn argument_matches_path(value: &Value, expected: &str) -> bool {
    ["path", "filePath", "file_path"].iter().any(|key| {
        value
            .get(key)
            .and_then(Value::as_str)
            .is_some_and(|observed| workspace_path_matches(expected, observed))
    })
}

fn argument_matches(value: &Value, keys: &[&str], expected: &str) -> bool {
    keys.iter()
        .any(|key| value.get(key).and_then(Value::as_str) == Some(expected))
}

fn workspace_path_matches(expected: &str, observed: &str) -> bool {
    if observed == expected {
        return true;
    }
    let expected = Path::new(expected);
    let observed = Path::new(observed);
    expected.is_relative() && observed.is_absolute() && observed.ends_with(expected)
}

pub(super) fn result_for_command(messages: &[ChatMessage], command: &str) -> Option<String> {
    matching_result(messages, |name, arguments| {
        tool_capability(name) == Some(Capability::Run)
            && super::tool_result::command_argument(arguments).as_deref() == Some(command)
    })
}

pub(super) fn plan_digest_verification(
    task: &str,
    current_turn: &[ChatMessage],
    tool_names: &[&str],
    change: &VerifiedChange<'_>,
    result: &mut Option<FinalResult>,
) -> Option<AgenticPlan> {
    let command = ["sha256sum -- ", change.target].concat();
    let Some(observed) = result_for_command(current_turn, &command) else {
        let tool = tool_for(tool_names, Capability::Run)?;
        return Some(plan_one(tool, json!({"command": command}).to_string()));
    };
    let digest = crate::source_fetch::sha256_hex(change.expected.as_bytes());
    if observed.split_whitespace().next() != Some(digest.as_str()) {
        return Some(AgenticPlan::Final(render_seeded_outcome(
            "coding_workspace_verification_failed",
            task,
            change.target,
        )?));
    }
    Some(record(AgenticPlan::Final(render_seeded_change_with_lists(
        change.intent,
        task,
        change.target,
        change.slots,
        change.list_slots,
    )?), FinalDisposition::Finding, "workspace_change_observed", result))
}

fn matching_result(
    messages: &[ChatMessage],
    matches: impl Fn(&str, &str) -> bool,
) -> Option<String> {
    messages
        .iter()
        .enumerate()
        .rev()
        .find_map(|(index, message)| {
            if !message.role.eq_ignore_ascii_case("tool") {
                return None;
            }
            let id = message.tool_call_id.as_deref()?;
            let call = messages[..index]
                .iter()
                .rev()
                .flat_map(|prior| prior.tool_calls.iter().rev())
                .find(|call| call.id == id)?;
            matches(&call.function.name, &call.function.arguments)
                .then(|| message.content.plain_text())
        })
}

pub(super) fn read_arguments(path: &str) -> String {
    json!({"path": path, "filePath": path, "file_path": path}).to_string()
}

changes.expected:
//! Grounded, verified workspace transformations learned from coding-task runs.
//!
//! The planner never edits request prose. It compiles a bounded transformation,
//! reads the client-owned bytes, executes the transformation in memory, applies
//! a compact edit or bounded replace-all operation, and accepts success only
//! after an exact content-digest observation. The same state machine composes
//! source creation with a second module-registration edit, so a multi-file
//! request cannot stop after its first observable effect.

use serde_json::{Value, json};
use std::path::Path;

use super::code_artifact::source_from_read_result;
use super::code_task::{
    render_rust_template, render_seeded_change, render_seeded_change_with_lists,
    render_seeded_outcome, rust_source_for_task,
};
use super::final_result::{FinalDisposition, FinalResult, record};
use super::general_planner::compose_edit_request;
use super::intent_router::edit_arguments;
use super::planner::{
    AgenticPlan, Capability, plan_one, tool_capability, tool_for, write_arguments,
};
use super::positional_edit::PositionalInsert;
use crate::normal_markov::{quoted_segments, unwrap_transport_quotes};
use crate::protocol::ChatMessage;
use crate::seed;
use crate::workspace_change_learning::{
    RewriteScope, execute_scoped_workspace_rewrite, is_identifier_word, word_scoped_matches,
};

#[derive(Debug, Clone, PartialEq, Eq)]
struct GroundedRewrite {
    target: String,
    pattern: String,
    replacement: String,
    /// How the pattern is allowed to match. Renaming an identifier is a
    /// word-scoped edit; replacing a quoted literal is a substring one -- or a
    /// word-scoped one when the new word contains the old (`smal` → `small`).
    scope: RewriteScope,
    /// Whether the request renamed a name (a word-scoped rename).
    renaming: bool,
    /// Whether the pattern must occur exactly once (a positional insertion's
    /// anchor), replaced once rather than everywhere.
    unique: bool,
    /// Whether the replacement holds the pattern, so it is applied in one
    /// pass rather than rewritten until no pattern is left (PR #1188 G78).
    single_pass: bool,
    /// The seed sentence that states the change, when it is not the
    /// rename/replace one (a positional insertion's).
    stated: Option<(&'static str, Vec<(&'static str, String)>)>,
    /// The pattern and replacement as the request wrote them, when it wrote
    /// `\n` / `\t` escapes the rewrite unescaped (see [`as_written`]).
    verbatim: Option<(String, String)>,
}

/// The template slots the seed sentences that state a rewrite fill.
const OLD_SLOT: &str = concat!("{", "old", "}");
const NEW_SLOT: &str = concat!("{", "new", "}");
const ANCHOR_SLOT: &str = concat!("{", "anchor", "}");

impl GroundedRewrite {
    /// The intent whose seed sentence states this change rather than merely
    /// reporting that the file was touched.
    const fn stated_intent(&self) -> &'static str {
        match self.stated {
            Some((intent, _)) => intent,
            None if self.renaming => "coding_identifier_renamed",
            None => "coding_text_replaced",
        }
    }

    /// The operands the seed sentence names, as template slots.
    fn stated_slots(&self) -> Vec<(&str, &str)> {
        match &self.stated {
            Some((_, slots)) => slots
                .iter()
                .map(|(slot, value)| (*slot, value.as_str()))
                .collect(),
            None => vec![
                (OLD_SLOT, self.pattern.as_str()),
                (NEW_SLOT, self.replacement.as_str()),
            ],
        }
    }
}

/// A change whose bytes are settled, awaiting the observation that confirms it.
///
/// `expected` is what the workspace should now hold; `intent` and `slots` are
/// the seed sentence that states the change once it does.
pub(super) struct VerifiedChange<'a> {
    pub(super) target: &'a str,
    pub(super) expected: &'a str,
    pub(super) intent: &'a str,
    pub(super) slots: &'a [(&'a str, &'a str)],
    pub(super) list_slots: &'a [(&'a str, &'a [String])],
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct CompositeModuleChange {
    source_path: String,
    source: String,
    registration_path: String,
    registration: String,
}

pub(super) fn plan_workspace_change_step(
    task: &str,
    messages: &[ChatMessage],
    tool_names: &[&str],
    result: &mut Option<FinalResult>,
) -> Option<AgenticPlan> {
    let task = unwrap_transport_quotes(task);
    // A continuation cue resumes this run rather than opening a new request,
    // so the read and write evidence gathered for it must survive the ping
    // (issue #1138): slicing at the last user message -- the cue itself --
    // restarted the read--write pair on every ping.
    let current_turn = &messages[super::planner::evidence_window_start(messages)..];
    // `Append the contents of a.txt to b.txt`: the source is read, and the
    // request is restated with its lines as the block placed (PR #1188 G50).
    let sourced = match sourced_request(task, current_turn) {
        Some(Sourced::Read(path)) => {
            let tool = tool_for(tool_names, Capability::Read)?;
            return Some(plan_one(tool, read_arguments(&path)));
        }
        Some(Sourced::Task(sourced)) => Some(sourced),
        None => None,
    };
    let task = sourced.as_deref().unwrap_or(task);

    if let Some(change) = composite_module_change(task) {
        return plan_composite_step(task, current_turn, tool_names, &change, result);
    }
    // Numbered lines moved to another file: placed there, then removed (G85).
    if let Some(order) = super::line_range_move::line_range_move(task) {
        return super::line_range_move::plan_line_range_move_step(
            task,
            current_turn,
            tool_names,
            &order,
            result,
        );
    }
    if let Some(change) = super::workspace_computed_change::grounded_line_change(task) {
        return super::workspace_computed_change::plan_computed_change_step(
            task,
            current_turn,
            tool_names,
            &change,
            result,
        );
    }
    if let Some(inserts) = insert_sequence(task) {
        return super::positional_edit::plan_insert_sequence_step(
            task,
            current_turn,
            tool_names,
            &inserts,
            result,
        );
    }
    // Several replacements asked in one sentence are made in order (G82).
    if let Some(change) = super::workspace_computed_change::grounded_replace_list(task) {
        return super::workspace_computed_change::plan_computed_change_step(
            task,
            current_turn,
            tool_names,
            &change,
            result,
        );
    }
    if let Some(rewrite) = grounded_rewrite(task) {
        return plan_rewrite_step(task, current_turn, tool_names, &rewrite, result);
    }
    let change = super::workspace_computed_change::grounded_computed_change(task)?;
    super::workspace_computed_change::plan_computed_change_step(
        task,
        current_turn,
        tool_names,
        &change,
        result,
    )
}

/// A request whose additive edit places another file's contents: the source
/// to read first, or the request restated with its lines.
enum Sourced {
    Read(String),
    Task(String),
}

/// `None` unless the request names a contents source and, restated, is an
/// additive edit the composers place.
fn sourced_request(task: &str, current_turn: &[ChatMessage]) -> Option<Sourced> {
    use super::contents_source::{contents_source, with_contents};
    let source = contents_source(task)?;
    let probe = with_contents(task, &source, "x");
    if insert_sequence(&probe).is_none()
        && super::workspace_computed_change::grounded_end_insertion(&probe).is_none()
    {
        return None;
    }
    let Some(read) = result_for_path(current_turn, Capability::Read, &source.path, None) else {
        return Some(Sourced::Read(source.path));
    };
    if super::code_artifact::source_from_agent_read_result(&read).is_none()
        && super::tool_result::failure_message(&read, false, true).is_some()
    {
        return None;
    }
    let contents = source_from_read_result(&read);
    Some(Sourced::Task(with_contents(task, &source, &contents)))
}

fn plan_rewrite_step(
    task: &str,
    current_turn: &[ChatMessage],
    tool_names: &[&str],
    rewrite: &GroundedRewrite,
    result: &mut Option<FinalResult>,
) -> Option<AgenticPlan> {
    let Some(read) = result_for_path(current_turn, Capability::Read, &rewrite.target, None) else {
        let tool = tool_for(tool_names, Capability::Read)?;
        return Some(plan_one(tool, read_arguments(&rewrite.target)));
    };
    let source = source_from_read_result(&read);
    let written = as_written(&source, rewrite);
    let rewrite = written.as_ref().unwrap_or(rewrite);
    let Some(updated) = rewritten_source(&source, rewrite) else {
        // A replace asked again finds its old text gone: that is the answer (G87).
        let absent = super::replace_list::absent_text_answer(
            task,
            &rewrite.target,
            &source,
            &rewrite.pattern,
            Some(&rewrite.replacement),
        );
        return Some(AgenticPlan::Final(match absent {
            Some(answer) => answer,
            None => render_seeded_outcome(
                "coding_workspace_verification_failed",
                task,
                &rewrite.target,
            )?,
        }));
    };

    let occurrences = match rewrite.scope {
        RewriteScope::Substring => source.match_indices(&rewrite.pattern).count(),
        RewriteScope::Word => word_scoped_matches(&source, &rewrite.pattern).len(),
    };
    if occurrences > 1
        && let Some(answer) = super::edit_scope::scoped_decline(task, &rewrite.target, &source)
    {
        return Some(AgenticPlan::Final(answer));
    }
    if occurrences == 1 {
        // The bare pattern when it is unique in the file; otherwise the
        // smallest unique run of changed lines -- the edit tool refuses an
        // `oldString` it finds twice, and `smal` also sits inside `small`.
        let edit = if rewrite.unique {
            anchored_lines(&source, rewrite).map(|(_, old, new)| (old, new))
        } else if source.matches(rewrite.pattern.as_str()).count() == 1 {
            Some((rewrite.pattern.clone(), rewrite.replacement.clone()))
        } else {
            changed_lines_edit(&source, &updated)
        };
        if let Some(tool) = tool_for(tool_names, Capability::Edit)
            && let Some((old, new)) = edit
        {
            if result_for_edit(current_turn, &rewrite.target, &old, &new).is_none() {
                return Some(plan_one(tool, edit_arguments(&rewrite.target, &old, &new)));
            }
            return plan_digest_verification(
                task,
                current_turn,
                tool_names,
                &VerifiedChange {
                    target: &rewrite.target,
                    expected: &updated,
                    intent: rewrite.stated_intent(),
                    slots: &rewrite.stated_slots(),
                    list_slots: &[],
                },
                result,
            );
        }
    } else if tool_for(tool_names, Capability::Edit).is_some()
        && let Some(command) = repeated_identifier_rewrite_command(rewrite)
        && let Some(tool) = tool_for(tool_names, Capability::Run)
    {
        if result_for_command(current_turn, &command).is_none() {
            return Some(plan_one(tool, json!({"command": command}).to_string()));
        }
        return plan_digest_verification(
            task,
            current_turn,
            tool_names,
            &VerifiedChange {
                target: &rewrite.target,
                expected: &updated,
                intent: rewrite.stated_intent(),
                slots: &rewrite.stated_slots(),
                list_slots: &[],
            },
            result,
        );
    }

    if result_for_path(
        current_turn,
        Capability::Write,
        &rewrite.target,
        Some(&updated),
    )
    .is_none()
    {
        let tool = tool_for(tool_names, Capability::Write)?;
        return Some(plan_one(tool, write_arguments(&rewrite.target, &updated)));
    }
    let command = format!("cat {}", rewrite.target);
    let Some(observed) = result_for_command(current_turn, &command) else {
        let tool = tool_for(tool_names, Capability::Run)?;
        return Some(plan_one(tool, json!({"command": command}).to_string()));
    };
    if observed != updated {
        return Some(AgenticPlan::Final(render_seeded_outcome(
            "coding_workspace_verification_failed",
            task,
            &rewrite.target,
        )?));
    }
    Some(record(
        AgenticPlan::Final(render_seeded_change(
            rewrite.stated_intent(),
            task,
            &rewrite.target,
            &rewrite.stated_slots(),
        )?),
        FinalDisposition::Finding,
        "workspace_change_observed",
        result,
    ))
}

fn plan_composite_step(
    task: &str,
    current_turn: &[ChatMessage],
    tool_names: &[&str],
    change: &CompositeModuleChange,
    result: &mut Option<FinalResult>,
) -> Option<AgenticPlan> {
    if result_for_path(
        current_turn,
        Capability::Write,
        &change.source_path,
        Some(&change.source),
    )
    .is_none()
    {
        let tool = tool_for(tool_names, Capability::Write)?;
        return Some(plan_one(
            tool,
            write_arguments(&change.source_path, &change.source),
        ));
    }

    let source_command = format!("cat {}", change.source_path);
    let Some(observed_source) = result_for_command(current_turn, &source_command) else {
        let tool = tool_for(tool_names, Capability::Run)?;
        return Some(plan_one(
            tool,
            json!({"command": source_command}).to_string(),
        ));
    };
    if observed_source != change.source {
        return Some(AgenticPlan::Final(render_seeded_outcome(
            "coding_workspace_verification_failed",
            task,
            &change.source_path,
        )?));
    }

    let Some(read) = result_for_path(
        current_turn,
        Capability::Read,
        &change.registration_path,
        None,
    ) else {
        let tool = tool_for(tool_names, Capability::Read)?;
        return Some(plan_one(tool, read_arguments(&change.registration_path)));
    };
    let current = source_from_read_result(&read);
    let updated = insert_registration(&current, &change.registration);
    let registered = ["`", change.registration.trim(), "`"].concat();
    if updated == current {
        return Some(record(
            AgenticPlan::Final(render_seeded_change(
                "coding_member_already_present",
                task,
                &change.registration_path,
                &[("{members}", &registered)],
            )?),
            FinalDisposition::Finding,
            "workspace_change_observed",
            result,
        ));
    }

    if let Some((old, new)) = compact_registration_edit(&current, &change.registration)
        && let Some(tool) = tool_for(tool_names, Capability::Edit)
    {
        if result_for_edit(current_turn, &change.registration_path, &old, &new).is_none() {
            return Some(plan_one(
                tool,
                edit_arguments(&change.registration_path, &old, &new),
            ));
        }
        return plan_digest_verification(
            task,
            current_turn,
            tool_names,
            &VerifiedChange {
                target: &change.registration_path,
                expected: &updated,
                intent: "coding_member_inserted",
                slots: &[("{members}", &registered)],
                list_slots: &[],
            },
            result,
        );
    }

    if result_for_path(
        current_turn,
        Capability::Write,
        &change.registration_path,
        Some(&updated),
    )
    .is_none()
    {
        let tool = tool_for(tool_names, Capability::Write)?;
        return Some(plan_one(
            tool,
            write_arguments(&change.registration_path, &updated),
        ));
    }

    let registration_command = format!("cat {}", change.registration_path);
    let Some(observed_registration) = result_for_command(current_turn, &registration_command)
    else {
        let tool = tool_for(tool_names, Capability::Run)?;
        return Some(plan_one(
            tool,
            json!({"command": registration_command}).to_string(),
        ));
    };
    if observed_registration != updated {
        return Some(AgenticPlan::Final(render_seeded_outcome(
            "coding_workspace_verification_failed",
            task,
            &change.registration_path,
        )?));
    }
    Some(record(
        AgenticPlan::Final(render_seeded_change(
            "coding_member_inserted",
            task,
            &change.registration_path,
            &[("{members}", &registered)],
        )?),
        FinalDisposition::Finding,
        "workspace_change_observed",
        result,
    ))
}

/// The file after `rewrite`, or `None` when it cannot apply. A positional
/// insertion replaces its one anchor occurrence; an anchor found zero or
/// several times does not say where the line goes.
/// The rewrite as the request wrote it, when the file holds no unescaped
/// pattern but holds the pattern as written (source code quoting `'\n'`,
/// PR #1188 G65).
fn as_written(source: &str, rewrite: &GroundedRewrite) -> Option<GroundedRewrite> {
    let (pattern, replacement) = rewrite.verbatim.clone()?;
    if (rewrite.pattern != pattern && source.contains(&rewrite.pattern))
        || !source.contains(&pattern)
    {
        return None;
    }
    Some(GroundedRewrite {
        pattern,
        replacement,
        verbatim: None,
        ..rewrite.clone()
    })
}

fn rewritten_source(source: &str, rewrite: &GroundedRewrite) -> Option<String> {
    if rewrite.single_pass {
        return source
            .contains(rewrite.pattern.as_str())
            .then(|| source.replace(rewrite.pattern.as_str(), &rewrite.replacement));
    }
    if rewrite.unique {
        let (start, old, new) = anchored_lines(source, rewrite)?;
        return Some([&source[..start], new.as_str(), &source[start + old.len()..]].concat());
    }
    execute_scoped_workspace_rewrite(
        source,
        &rewrite.pattern,
        &rewrite.replacement,
        rewrite.scope,
    )
    .ok()
    .map(|execution| execution.output)
}

/// A positional insertion's one anchor occurrence widened to the whole lines
/// it sits on, as `(start, old_lines, new_lines)`, or `None` unless the anchor
/// occurs exactly once. The inserted text is a line, so an anchor that is only
/// part of a line (`after the line containing '| T20 |'`) must not split it.
fn anchored_lines(source: &str, rewrite: &GroundedRewrite) -> Option<(usize, String, String)> {
    let (pattern, replacement) = (rewrite.pattern.as_str(), rewrite.replacement.as_str());
    let mut found = source.match_indices(pattern).map(|(at, _)| at);
    let (Some(at), None) = (found.next(), found.next()) else {
        return None;
    };
    let start = source[..at].rfind('\n').map_or(0, |newline| newline + 1);
    let tail = at + pattern.len();
    let end = if pattern.ends_with('\n') {
        tail - 1
    } else {
        source[tail..]
            .find('\n')
            .map_or(source.len(), |newline| tail + newline)
    };
    let old = &source[start..end];
    let new = replacement.strip_prefix(pattern).map_or_else(
        || [&replacement[..replacement.len() - pattern.len()], old].concat(),
        |rest| [old, rest].concat(),
    );
    Some((start, old.to_owned(), new))
}

/// The smallest run of whole lines holding every change from `source` to
/// `updated`, as an edit pair, when that run occurs once in `source`.
pub(super) fn changed_lines_edit(source: &str, updated: &str) -> Option<(String, String)> {
    const MAX_EDIT_BYTES: usize = 4096;
    let prefix = source
        .bytes()
        .zip(updated.bytes())
        .take_while(|(left, right)| left == right)
        .count();
    let limit = source.len().min(updated.len()) - prefix;
    let suffix = source
        .bytes()
        .rev()
        .zip(updated.bytes().rev())
        .take(limit)
        .take_while(|(left, right)| left == right)
        .count();
    // Byte positions only meet `\n`, so `start` and `end` fall on line -- and
    // therefore character -- boundaries even when the first or last differing
    // byte sits inside a multi-byte character.
    let bytes = source.as_bytes();
    let line_start = |before: usize| {
        bytes[..before]
            .iter()
            .rposition(|byte| *byte == b'\n')
            .map_or(0, |at| at + 1)
    };
    let mut start = line_start(prefix);
    let end = bytes[source.len() - suffix..]
        .iter()
        .position(|byte| *byte == b'\n')
        .map_or(source.len(), |at| source.len() - suffix + at);
    // Lines inserted between two lines change none: the line above carries
    // them.
    if start == end && start > 0 {
        start = line_start(start - 1);
    }
    let old = &source[start..end];
    let new = &updated[start..updated.len() - (source.len() - end)];
    (!old.is_empty() && old.len() <= MAX_EDIT_BYTES && source.matches(old).count() == 1)
        .then(|| (old.to_owned(), new.to_owned()))
}

/// `Insert 'x' after the line 'y' in f`: the anchor line, replaced once by the
/// anchor beside the new line, stated by the position meaning that placed it.
fn grounded_positional_insert(task: &str) -> Option<GroundedRewrite> {
    let (target, anchor, replacement) = super::positional_edit::compose_positional_insert(task)?;
    let after_anchor = [anchor.as_str(), "\n"].concat();
    let (after, inserted) = if let Some(inserted) = replacement.strip_prefix(&after_anchor) {
        (true, inserted.to_owned())
    } else {
        let before_anchor = ["\n", anchor.as_str()].concat();
        (false, replacement.strip_suffix(&before_anchor)?.to_owned())
    };
    let intent = super::positional_edit::insert_intent(after, &inserted);
    Some(GroundedRewrite {
        target,
        stated: Some((
            intent,
            vec![(NEW_SLOT, inserted), (ANCHOR_SLOT, anchor.clone())],
        )),
        pattern: anchor,
        replacement,
        scope: RewriteScope::Substring,
        renaming: false,
        unique: true,
        single_pass: false,
        verbatim: None,
    })
}

/// Every insert the request asks for, each its own anchored edit.
///
/// Several clauses (`…, and insert …`), an anchor named by the line it
/// follows (T31, T34), lines rebased on the anchor (G16), or one insert whose
/// anchor is a whole line also found inside others (`the line 'b'`).
fn insert_sequence(task: &str) -> Option<Vec<PositionalInsert>> {
    super::positional_edit::positional_inserts(task)
}

fn grounded_rewrite(task: &str) -> Option<GroundedRewrite> {
    if let Some(positional) = grounded_positional_insert(task) {
        return Some(positional);
    }
    let (target, old_clause, new_clause) = compose_edit_request(task)?;
    let renaming = seed::lexicon().mentions_role(
        seed::ROLE_CODING_IDENTIFIER_RENAME_ACTION,
        &task.to_lowercase(),
    );
    // A request that names a line replaces whole lines
    // (`grounded_line_replacement`).
    if !renaming && super::workspace_computed_change::names_line(task) {
        return None;
    }
    // Both operands have to be literals the request actually quoted, so prose
    // ("replace the old header with something clearer") is never rewritten as
    // bytes. What that cannot be is a count: requiring the request to hold
    // *exactly* two quoted segments made every other pair of delimiters in the
    // prompt disqualify the edit, and this repository's own prose backticks the
    // file it names. The issue #1028 ladder node "In the file
    // `src/protocol_memory.rs`, replace \"request_history\" with
    // \"conversation_history\"" quotes three things and states one replacement.
    // Asking whether each clause *is* quoted keeps the guarantee and drops the
    // arithmetic.
    // The edit request unescapes `\n` / `\t` in its literals, so the quoted
    // segments are compared unescaped too: a multi-line replacement written
    // with `\n` was otherwise not "quoted", and the general fallback wrote its
    // new text over the whole file (PR #1188 sub-agent gap 3).
    let quoted: Vec<String> = quoted_segments(task)
        .iter()
        .map(String::as_str)
        .map(super::positional_edit::unescape_prose_newlines)
        .collect();
    // A literal quoted whole counts even when backtick spans inside it pair
    // among themselves (PR #1188 G63).
    let is_quoted =
        |value: &String| quoted.contains(value) || crate::normal_markov::quotes_whole(task, value);
    let operands = if is_quoted(&old_clause) && is_quoted(&new_clause) {
        Some((old_clause, new_clause))
    } else if renaming {
        Some((
            identifier_tokens(&old_clause).next_back()?.to_owned(),
            identifier_tokens(&new_clause).next()?.to_owned(),
        ))
    } else {
        None
    }?;
    let (old, new) = operands;
    let as_quoted = |text: &str| {
        quoted_segments(task)
            .into_iter()
            .find(|raw| raw != text && super::positional_edit::unescape_prose_newlines(raw) == text)
            .unwrap_or_else(|| text.to_owned())
    };
    let verbatim = (as_quoted(&old) != old || as_quoted(&new) != new)
        .then(|| (as_quoted(&old), as_quoted(&new)));
    // A rename names a *word*, so the edit is word-scoped whichever way the
    // request spelled its operands. Without that scope the most ordinary rename
    // there is -- giving a name a prefix or a suffix -- has to be refused, since
    // an unanchored substring rewrite that reintroduces its own pattern never
    // terminates.
    //
    // A word replaced by a longer word that contains it (`smal` → `small`, a
    // typo fix) is only safe word by word for the same reason.
    let words = is_identifier_word(&old) && is_identifier_word(&new);
    let scope = if words && (renaming || new.contains(&old)) {
        RewriteScope::Word
    } else {
        RewriteScope::Substring
    };
    if old.is_empty() || old == new {
        return None;
    }
    // A new text holding the old one (`key 3` → `key 33`) is replaced in one
    // pass over the file, never rewritten again inside its own result (PR
    // #1188 G78).
    let single_pass = scope == RewriteScope::Substring && new.contains(&old);
    Some(GroundedRewrite {
        target,
        pattern: old,
        replacement: new,
        scope,
        renaming: renaming && scope == RewriteScope::Word,
        unique: false,
        single_pass,
        stated: None,
        verbatim,
    })
}

// This is a seed-template placeholder, not a Rust formatting argument.
#[allow(clippy::literal_string_with_formatting_args)]
fn composite_module_change(task: &str) -> Option<CompositeModuleChange> {
    let lowered = task.to_lowercase();
    if !seed::lexicon().mentions_role(seed::ROLE_CODING_MODULE_REGISTRATION_ACTION, &lowered) {
        return None;
    }
    let generated = rust_source_for_task(task)?;
    let registration_path = rust_paths(task)
        .into_iter()
        .find(|path| path != &generated.path)?;
    let module = generated.path.rsplit('/').next()?.strip_suffix(".rs")?;
    if !valid_identifier(module) {
        return None;
    }
    let registration =
        render_rust_template("coding_source_module_registration", &[("{module}", module)])?;
    Some(CompositeModuleChange {
        source_path: generated.path,
        source: generated.content,
        registration_path,
        registration,
    })
}

fn insert_registration(source: &str, registration: &str) -> String {
    if source
        .lines()
        .any(|line| line.trim() == registration.trim())
    {
        return source.to_owned();
    }
    let mut updated = source.to_owned();
    if !updated.is_empty() && !updated.ends_with('\n') {
        updated.push('\n');
    }
    updated.push_str(registration);
    updated
}

fn compact_registration_edit(source: &str, registration: &str) -> Option<(String, String)> {
    const MAX_SUFFIX_BYTES: usize = 4096;
    let mut starts = source
        .match_indices('\n')
        .map(|(index, _)| index + 1)
        .filter(|start| *start < source.len())
        .collect::<Vec<_>>();
    starts.insert(0, 0);
    for start in starts.into_iter().rev() {
        let suffix = &source[start..];
        if suffix.len() > MAX_SUFFIX_BYTES {
            break;
        }
        if source.match_indices(suffix).count() != 1 {
            continue;
        }
        let mut replacement = suffix.to_owned();
        if !replacement.ends_with('\n') {
            replacement.push('\n');
        }
        replacement.push_str(registration);
        return Some((suffix.to_owned(), replacement));
    }
    None
}

fn repeated_identifier_rewrite_command(rewrite: &GroundedRewrite) -> Option<String> {
    if !shell_safe_identifier(&rewrite.pattern) || !shell_safe_identifier(&rewrite.replacement) {
        return None;
    }
    // The in-memory execution and the command the client runs have to agree on
    // what a match is, so a word-scoped rewrite asks for whole words too.
    let pattern = match rewrite.scope {
        RewriteScope::Substring => rewrite.pattern.clone(),
        RewriteScope::Word => format!("\\b{}\\b", rewrite.pattern),
    };
    // `perl -pi -e`, not `sed -i` (issue #1110). GNU and BSD sed disagree about
    // both halves of that command: BSD `-i` reads the script as its backup
    // suffix, and BSD sed has no `\b`. On macOS every rename therefore failed
    // with `bad flag in substitute command`, the file was left unchanged, and
    // Formal AI reported the mismatch as its own verification failure -- a
    // confident failure report instead of a rename. perl's `-pi -e` and `\b`
    // mean the same thing on both, and perl ships with macOS and the runners.
    // Both identifiers are `[A-Za-z0-9_]` by `shell_safe_identifier`, so
    // neither side can carry a regex or shell metacharacter.
    // Assembled from named parts rather than one template string: the prose
    // detector reads `perl -pi -e ...` as a multi-word phrase (two alphabetic
    // runs, one of three letters) and would have it live in `data/seed`, which
    // is the wrong home for a shell invocation. Naming the pieces says what
    // each is, and none of them reads as a sentence.
    let script = format!("'s/{pattern}/{}/g'", rewrite.replacement);
    Some(["perl", "-pi", "-e", &script, "--", &rewrite.target].join(" "))
}

fn shell_safe_identifier(identifier: &str) -> bool {
    !identifier.is_empty()
        && identifier
            .chars()
            .all(|character| character.is_ascii_alphanumeric() || character == '_')
}

pub(super) fn identifier_tokens(text: &str) -> impl DoubleEndedIterator<Item = &str> {
    text.split(|character: char| !character.is_ascii_alphanumeric() && character != '_')
        .filter(|token| valid_identifier(token))
}

fn valid_identifier(identifier: &str) -> bool {
    let mut characters = identifier.chars();
    characters
        .next()
        .is_some_and(|first| first.is_ascii_alphabetic() || first == '_')
        && characters.all(|character| character.is_ascii_alphanumeric() || character == '_')
        && !seed::lexicon()
            .words_for_role(seed::ROLE_IDENTIFIER_RESERVED_WORD)
            .iter()
            .any(|reserved| reserved == identifier)
}

fn rust_paths(task: &str) -> Vec<String> {
    let mut paths = Vec::new();
    for (suffix, _) in task.match_indices(".rs") {
        let end = suffix + 3;
        let start = task[..end]
            .char_indices()
            .rev()
            .take_while(|(_, character)| {
                character.is_ascii_alphanumeric() || matches!(character, '_' | '-' | '.' | '/')
            })
            .last()
            .map_or(0, |(index, _)| index);
        let path = &task[start..end];
        if !path.is_empty()
            && !path.starts_with('/')
            && !path.split('/').any(|component| component == "..")
            && !paths.iter().any(|existing| existing == path)
        {
            paths.push(path.to_owned());
        }
    }
    paths
}

pub(super) fn result_for_path(
    messages: &[ChatMessage],
    capability: Capability,
    path: &str,
    expected_content: Option<&str>,
) -> Option<String> {
    matching_result(messages, |name, arguments| {
        if tool_capability(name) != Some(capability) {
            return false;
        }
        let Ok(value) = serde_json::from_str::<Value>(arguments) else {
            return false;
        };
        let matches_path = ["path", "filePath", "file_path"].iter().any(|key| {
            value
                .get(key)
                .and_then(Value::as_str)
                .is_some_and(|observed| workspace_path_matches(path, observed))
        });
        matches_path
            && expected_content.is_none_or(|expected| {
                value.get("content").and_then(Value::as_str) == Some(expected)
            })
    })
}

pub(super) fn result_for_edit(
    messages: &[ChatMessage],
    path: &str,
    old: &str,
    new: &str,
) -> Option<String> {
    matching_result(messages, |name, arguments| {
        if tool_capability(name) != Some(Capability::Edit) {
            return false;
        }
        let Ok(value) = serde_json::from_str::<Value>(arguments) else {
            return false;
        };
        argument_matches_path(&value, path)
            && argument_matches(&value, &["oldString", "old_string", "old_str", "old"], old)
            && argument_matches(&value, &["newString", "new_string", "new_str", "new"], new)
    })
}

fn argument_matches_path(value: &Value, expected: &str) -> bool {
    ["path", "filePath", "file_path"].iter().any(|key| {
        value
            .get(key)
            .and_then(Value::as_str)
            .is_some_and(|observed| workspace_path_matches(expected, observed))
    })
}

fn argument_matches(value: &Value, keys: &[&str], expected: &str) -> bool {
    keys.iter()
        .any(|key| value.get(key).and_then(Value::as_str) == Some(expected))
}

fn workspace_path_matches(expected: &str, observed: &str) -> bool {
    if observed == expected {
        return true;
    }
    let expected = Path::new(expected);
    let observed = Path::new(observed);
    expected.is_relative() && observed.is_absolute() && observed.ends_with(expected)
}

pub(super) fn result_for_command(messages: &[ChatMessage], command: &str) -> Option<String> {
    matching_result(messages, |name, arguments| {
        tool_capability(name) == Some(Capability::Run)
            && super::tool_result::command_argument(arguments).as_deref() == Some(command)
    })
}

pub(super) fn plan_digest_verification(
    task: &str,
    current_turn: &[ChatMessage],
    tool_names: &[&str],
    change: &VerifiedChange<'_>,
    result: &mut Option<FinalResult>,
) -> Option<AgenticPlan> {
    let command = ["sha256sum -- ", change.target].concat();
    let Some(observed) = result_for_command(current_turn, &command) else {
        let tool = tool_for(tool_names, Capability::Run)?;
        return Some(plan_one(tool, json!({"command": command}).to_string()));
    };
    let digest = crate::source_fetch::sha256_hex(change.expected.as_bytes());
    if observed.split_whitespace().next() != Some(digest.as_str()) {
        return Some(AgenticPlan::Final(render_seeded_outcome(
            "coding_workspace_verification_failed",
            task,
            change.target,
        )?));
    }
    Some(record(
        AgenticPlan::Final(render_seeded_change_with_lists(
            change.intent,
            task,
            change.target,
            change.slots,
            change.list_slots,
        )?),
        FinalDisposition::Finding,
        "workspace_change_observed",
        result,
    ))
}

fn matching_result(
    messages: &[ChatMessage],
    matches: impl Fn(&str, &str) -> bool,
) -> Option<String> {
    messages
        .iter()
        .enumerate()
        .rev()
        .find_map(|(index, message)| {
            if !message.role.eq_ignore_ascii_case("tool") {
                return None;
            }
            let id = message.tool_call_id.as_deref()?;
            let call = messages[..index]
                .iter()
                .rev()
                .flat_map(|prior| prior.tool_calls.iter().rev())
                .find(|call| call.id == id)?;
            matches(&call.function.name, &call.function.arguments)
                .then(|| message.content.plain_text())
        })
}

pub(super) fn read_arguments(path: &str) -> String {
    json!({"path": path, "filePath": path, "file_path": path}).to_string()
}

changes.before:
//! Workspace changes whose new bytes are computed from the file they change
//! (PR #1188 dogfooding): text added at one end of a file, quoted text
//! removed from it, a configuration setting assigned a new value, a named
//! function removed whole.
//!
//! Each is read → compute → smallest unique edit (or the whole file) → digest
//! check → the seeded sentence that states the change, the same state machine
//! [`super::workspace_change`] runs for grounded rewrites. Before these, an
//! append (`Append the line 'third line' to notes.txt.`) reached the
//! general-change fallback and was written as the *whole* file.

use super::final_result::FinalResult;
use super::code_artifact::source_from_read_result;
use super::code_task::render_seeded_outcome;
use super::general_planner::compose_edit_request;
use super::intent_router::edit_arguments;
use super::line_removal::{
    bare_line, removed_declarations, removed_line_indices, removed_lines, removed_literal,
};
use super::planner::{AgenticPlan, Capability, plan_one, tool_for, write_arguments};
use super::workspace_change::{
    VerifiedChange, changed_lines_edit, identifier_tokens, plan_digest_verification,
    read_arguments, result_for_edit, result_for_path,
};
use super::workspace_line_operation::{
    LineOperation, drops_most_of_file, grounded_line_operation, named_target_and_payloads,
};
use super::write_request::{
    bare_surfaces, clean_cue_token, clean_path_token, looks_like_file_path, safe_relative_path,
    tokens,
};
use crate::normal_markov::{quoted_segment_spans, quoted_segments};
use crate::protocol::ChatMessage;
use crate::seed;
use crate::workspace_change_learning::{
    RewriteScope, execute_scoped_workspace_rewrite, is_identifier_word,
};

const MAX_ANCHOR_BYTES: usize = 4096;

/// How a computed change derives the file's new bytes.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(super) enum Computation {
    /// Quoted text placed as the last (`at_end`) or the first line; lines
    /// given under the request keep their shared `indentation` when the file
    /// has lines indented exactly so (PR #1188 G16).
    EndInsertion {
        text: String,
        at_end: bool,
        indentation: Option<String>,
    },
    /// Every line that is exactly `text`, else its one in-line occurrence.
    Removal { text: String },
    /// Whole lines (the request names a line): see `removed_line_indices`.
    LineRemoval { text: String, containing: bool },
    /// The one line assigning `key` (holding `held`, when stated) gets
    /// `value`, in the file's own quoting.
    Setting {
        key: String,
        value: String,
        held: Option<String>,
    },
    /// Every line that is `old` becomes `new` (the request names a line), or
    /// only the first one after `context`.
    LineReplacement {
        listed: bool,
        old: String,
        new: String,
        context: Option<String>,
        rebase: bool,
    },
    /// Every whole-word `word` becomes its discovered `correction`.
    TypoFix { word: String, correction: String },
    /// The functions the file declares under these names go whole, with the
    /// comment and attribute lines directly above them.
    DeclarationRemoval { names: Vec<String> },
    /// A whole-line operation: numbered, adjacent, moved or swapped lines.
    Line(LineOperation),
    /// `text` placed at one end of the Markdown section under `heading`
    /// (PR #1188 G35).
    Section {
        heading: String,
        text: String,
        at_end: bool,
    },
    /// Each `(old, new)` pair replaced everywhere, in order (PR #1188 G82).
    ReplaceList { pairs: Vec<(String, String)> },
}

/// A computed change: the file, how its bytes are computed, and the seed
/// sentence (intent and slots) that states it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(super) struct ComputedChange {
    pub(super) target: String,
    pub(super) computation: Computation,
    pub(super) intent: &'static str,
    pub(super) slots: Vec<(&'static str, String)>,
}

/// The first computed change `task` asks for, if any.
pub(super) fn grounded_computed_change(task: &str) -> Option<ComputedChange> {
    grounded_end_insertion(task)
        .or_else(|| grounded_removal(task))
        .or_else(|| grounded_declaration_removal(task))
        .or_else(|| grounded_line_replacement(task))
        .or_else(|| grounded_setting(task))
        .or_else(|| grounded_typo_fix(task))
}

/// `Fix the typo 'smal' in README.md`: the seeded `typo_fix_lead` with one
/// quoted word and one path, and no stated correction. The correction is
/// discovered ([`super::spelling::corrected_spelling`]), and the change is the
/// word-scoped replacement a stated correction would have made.
fn grounded_typo_fix(task: &str) -> Option<ComputedChange> {
    if !mentions("typo_fix_lead", task) {
        return None;
    }
    let (target, word) = quoted_payload_and_path(task)?;
    if !is_identifier_word(&word) {
        return None;
    }
    let correction = super::spelling::corrected_spelling(&word)?;
    Some(ComputedChange {
        target,
        intent: "coding_text_replaced",
        slots: vec![("{old}", word.clone()), ("{new}", correction.clone())],
        computation: Computation::TypoFix { word, correction },
    })
}

fn mentions(role: &str, task: &str) -> bool {
    seed::lexicon().mentions_role(role, &sentence_words(task))
}

/// The marks that end a sentence or a clause.
const SENTENCE_MARKS: [char; 11] = [
    '.', '!', '?', ';', ':', ',', '\u{0964}', '\u{0965}', '\u{3002}', '\u{ff01}', '\u{ff1f}',
];

/// The lowered request with the marks that end a sentence or clause set off
/// as spaces, so a verb that closes its sentence (`… पंक्ति हटाओ।`, `…
/// удали.`) is still a whole word. A dot inside a token (`t.md`) is not
/// followed by a space and stays.
pub(super) fn sentence_words(task: &str) -> String {
    let lowered = task.to_lowercase();
    let characters: Vec<char> = lowered.chars().collect();
    let mut out = String::with_capacity(lowered.len());
    let mut index = 0;
    while index < characters.len() {
        let mut end = index;
        while end < characters.len() && SENTENCE_MARKS.contains(&characters[end]) {
            end += 1;
        }
        if end > index && characters.get(end).is_none_or(|next| next.is_whitespace()) {
            out.push(' ');
            index = end;
        } else {
            out.push(characters[index]);
            index += 1;
        }
    }
    out
}

/// Whether the request is about text inside a file: it quotes a payload that
/// is not a path, or names a line (the seeded `line` meaning) or another unit
/// of text (`file_text_unit`: word, phrase, occurrence, text, in every
/// registered language) outside its quotes. A destructive shell intent never
/// reads such a request as deleting the file (PR #1188).
pub(super) fn edits_inside_a_file(prompt: &str) -> bool {
    if quoted_segment_spans(prompt)
        .iter()
        .map(|segment| segment.text.trim())
        .any(|text| !text.is_empty() && !super::shell_command::looks_like_a_path(text))
    {
        return true;
    }
    let outside = crate::engine::normalize_prompt(
        &crate::solver_handlers::text_outside_quoted_segments(&without_path_words(prompt)),
    )
    .to_lowercase();
    seed::lexicon()
        .meaning("line")
        .is_some_and(|meaning| meaning.evidenced_in(&outside))
        || seed::lexicon().mentions_role("file_text_unit", &outside)
}

/// Whether the request names a line outside its quotes: the seeded `line`
/// meaning (`the line containing '…'`, `lines`, `строку`, `पंक्ति`, `的行`).
pub(super) fn names_line(task: &str) -> bool {
    // A path's own words are no line: `x-line.lino` names a file (PR #1188 G83).
    seed::lexicon()
        .meaning("line")
        .is_some_and(|meaning| meaning.evidenced_in(&outside_quotes(&without_path_words(task))))
}

/// `task` with every unquoted path token blanked.
///
/// A path's own words (`x-line.lino`, `line-budget.lino`) never read as the
/// words of the request (PR #1188 G83; mirrors `withoutPathWords`).
pub(super) fn without_path_words(task: &str) -> String {
    let segments = quoted_segment_spans(task);
    let mut out = task.to_owned();
    for token in super::write_request::tokens(task).iter().rev() {
        if segments
            .iter()
            .any(|segment| token.start < segment.end && token.end > segment.start)
        {
            continue;
        }
        let path = super::write_request::clean_path_token(token.text);
        if super::write_request::looks_like_file_path(path) {
            out.replace_range(token.start..token.end, &" ".repeat(token.end - token.start));
        }
    }
    out
}

/// The lowered request outside its quotes.
fn outside_quotes(task: &str) -> String {
    let outside = crate::solver_handlers::text_outside_quoted_segments(task);
    crate::engine::normalize_prompt(&outside).to_lowercase()
}

/// The one workspace path a request names and its one quoted segment that is
/// not that path. An unquoted path outranks a quoted one, which is then the
/// payload (PR #1188 T35).
fn quoted_payload_and_path(task: &str) -> Option<(String, String)> {
    let (target, payloads) = named_target_and_payloads(task)?;
    let [payload] = payloads.as_slice() else {
        return None;
    };
    Some((target, payload.clone()))
}

/// A whole-line operation (numbered, adjacent, moved or swapped lines) as a
/// computed change. It is read before a rewrite: `move 'x' after 'y'` is not
/// an insertion (PR #1188).
/// Several quoted replacements in one file, asked in one sentence, as one
/// computed change (PR #1188 G82; mirrors `groundedReplaceList`).
pub(super) fn grounded_replace_list(task: &str) -> Option<ComputedChange> {
    let (target, pairs) = super::replace_list::replace_list(task)?;
    let listed: Vec<String> = pairs
        .iter()
        .map(|(old, new)| format!("`{old}` → `{new}`"))
        .collect();
    Some(ComputedChange {
        target,
        intent: "coding_texts_replaced",
        slots: vec![
            (concat!("{", "pairs", "}"), listed.join(", ")),
            (concat!("{", "count", "}"), pairs.len().to_string()),
        ],
        computation: Computation::ReplaceList { pairs },
    })
}

pub(super) fn grounded_line_change(task: &str) -> Option<ComputedChange> {
    let change = grounded_line_operation(task)?;
    Some(ComputedChange {
        target: change.target,
        computation: Computation::Line(change.operation),
        intent: change.intent,
        slots: change.slots,
    })
}

/// `Append 'x' to notes.txt`, `Prepend "x" to a.md`: positioned by the seeded
/// `file_edit_position_end` / `file_edit_position_start` meanings.
pub(super) fn grounded_end_insertion(task: &str) -> Option<ComputedChange> {
    // `Append these lines to f:` followed by lines: the first line is the
    // request and the lines under it are the text added, verbatim (PR #1188).
    let block = super::positional_edit::introduced_block(task);
    // Position cues are read outside the quoted payload: a line saying "at the
    // start of x" is text being appended (PR #1188 G64).
    let cues = block
        .as_ref()
        .map_or_else(|| outside_quotes(task), |block| sentence_words(block.head));
    let lexicon = seed::lexicon();
    let at_end = lexicon.mentions_role("file_edit_position_end", &cues);
    if at_end == lexicon.mentions_role("file_edit_position_start", &cues) {
        return None;
    }
    // `… at the end of the section '## Usage' in README.md` (PR #1188 G35).
    if block.is_none()
        && let Some(section) = super::markdown_section::section_scope(task, &outside_quotes(task))
    {
        let text = super::positional_edit::unescape_prose_newlines(&section.text);
        return Some(ComputedChange {
            target: section.target,
            intent: "file_edit_position_after",
            slots: vec![
                ("{new}", text.clone()),
                ("{anchor}", section.heading.clone()),
            ],
            computation: Computation::Section {
                heading: section.heading,
                text,
                at_end,
            },
        });
    }
    let (target, text, indentation) = if let Some(block) = block {
        let indentation = (!block.verbatim).then(|| block.indentation.to_owned());
        (block_target(block.head)?, block.text, indentation)
    } else if let Some((target, text)) = quoted_lines_and_path(task) {
        (target, text, None)
    } else {
        let (target, text) = quoted_payload_and_path(task)
            .or_else(|| blank_line_and_path(task))
            .or_else(|| line_payload_and_path(task))?;
        (
            target,
            super::positional_edit::unescape_prose_newlines(&text),
            None,
        )
    };
    Some(ComputedChange {
        target,
        // An empty line has no text to quote back; it is stated in its own words.
        intent: if text.is_empty() {
            "file_edit_blank_line"
        } else if at_end {
            "file_edit_position_end"
        } else {
            "file_edit_position_start"
        },
        slots: vec![("{new}", text.clone())],
        computation: Computation::EndInsertion {
            text,
            at_end,
            indentation,
        },
    })
}

/// Several quoted literals, joined only by seeded joiners and commas, are the
/// lines added, each its own line, as written (PR #1188 G53, G54).
fn quoted_lines_and_path(task: &str) -> Option<(String, String)> {
    let (target, payloads) = named_target_and_payloads(task)?;
    if payloads.len() < 2 {
        return None;
    }
    let text = super::positional_edit::joined_literal_lines(task, &target)?;
    Some((target, text))
}

/// `Delete the line 'x' from notes.txt`: the seeded `coding_text_remove_action`
/// with one quoted payload and one path, and no add action alongside it.
fn grounded_removal(task: &str) -> Option<ComputedChange> {
    if !mentions("coding_text_remove_action", task) || mentions("coding_member_add_action", task) {
        return None;
    }
    let (target, text) = quoted_payload_and_path(task)?;
    // A request that names a line removes whole lines, never only the
    // payload inside one (PR #1188 G60).
    let computation = if names_line(task) {
        let containing =
            seed::lexicon().mentions_role("line_containment_cue", &outside_quotes(task));
        Computation::LineRemoval {
            text: text.clone(),
            containing,
        }
    } else {
        Computation::Removal { text: text.clone() }
    };
    Some(ComputedChange {
        target,
        intent: "coding_text_remove",
        slots: vec![("{old}", text)],
        computation,
    })
}

/// `Delete the functions a and b from util.rs`: the seeded
/// `coding_text_remove_action` and `coding_declaration_noun` with no add
/// action, no quoted text and one named path. The names are the request's
/// identifiers; `removed_declarations` keeps those the file itself declares
/// as functions (mirrors `groundedDeclarationRemoval`, PR #1188 dogfooding).
fn grounded_declaration_removal(task: &str) -> Option<ComputedChange> {
    if !mentions("coding_text_remove_action", task)
        || mentions("coding_member_add_action", task)
        || !mentions("coding_declaration_noun", task)
        || !quoted_segment_spans(task).is_empty()
    {
        return None;
    }
    let mut paths: Vec<String> = super::positional_edit::unquoted_path_tokens(task)
        .iter()
        .map(|token| clean_path_token(token.text).to_owned())
        .filter(|path| looks_like_file_path(path) && safe_relative_path(path))
        .collect();
    paths.sort();
    paths.dedup();
    let [target] = paths.as_slice() else {
        return None;
    };
    let mut names: Vec<String> = Vec::new();
    for token in tokens(task) {
        if clean_path_token(token.text) == target {
            continue;
        }
        for name in identifier_tokens(token.text) {
            if !names.iter().any(|known| known == name) {
                names.push(name.to_owned());
            }
        }
    }
    if names.is_empty() {
        return None;
    }
    Some(ComputedChange {
        target: target.clone(),
        intent: "coding_text_remove",
        slots: vec![("{old}", names.join("`, `"))],
        computation: Computation::DeclarationRemoval { names },
    })
}

/// `Change the value of "debug" to true in config.json`: the seeded
/// `config_value_lead` names a setting; the edit request's old clause names its
/// key (quoted, or its last identifier) and the new clause its value.
///
/// `Change MAXIMUM_RATIO from 8 to 16 in p.rs` states the value the key holds
/// now (the seeded `file_edit_old_lead_cue`): the line assigning the key that
/// value is the one changed, and a key assigned nowhere leaves the stated
/// value itself, when it occurs once as a word (PR #1188 G2).
fn grounded_setting(task: &str) -> Option<ComputedChange> {
    let (target, old_clause, value) = compose_edit_request(task)?;
    let stated = super::workspace_setting::stated_old_value(&old_clause);
    if stated.is_none() && !mentions("config_value_lead", task) {
        return None;
    }
    // `set the contents of note.txt to hello` writes the file; its contents are
    // not a key (PR #1188 G68, issue #745).
    if stated.is_none() && mentions("file_contents_source_cue", task) {
        return None;
    }
    let key_clause = stated
        .as_ref()
        .map_or(old_clause.as_str(), |(key, _)| key.as_str());
    let quoted = quoted_segments(key_clause);
    let key = match quoted.as_slice() {
        [key] => key.clone(),
        _ => identifier_tokens(key_clause).next_back()?.to_owned(),
    };
    let value = value.trim().to_owned();
    if value.is_empty() {
        return None;
    }
    Some(ComputedChange {
        target,
        intent: "setting",
        slots: vec![("{old}", key.clone()), ("{new}", value.clone())],
        computation: Computation::Setting {
            key,
            value,
            held: stated.map(|(_, held)| held),
        },
    })
}

/// `Replace the line 'x' with 'y' in f`: the seeded `line` meaning outside
/// the quotes, both clauses quoted. A line replacement never touches text
/// inside a longer line (T32: `text pays` became `text "pay"s`). With a seeded
/// anchor context (`the line 'x' that follows the line 'z'`), the first such
/// line after `z` is the one replaced (T62).
fn grounded_line_replacement(task: &str) -> Option<ComputedChange> {
    if !names_line(task)
        || seed::lexicon().mentions_role(
            seed::ROLE_CODING_IDENTIFIER_RENAME_ACTION,
            &task.to_lowercase(),
        )
    {
        return None;
    }
    let context = super::positional_edit::anchor_context(task);
    let request = context.as_ref().map_or_else(
        || task.to_owned(),
        |(start, end, _)| [&task[..*start], " ", &task[*end..]].concat(),
    );
    let (target, original, replacement) = compose_edit_request(&request)?;
    if super::positional_edit::compose_positional_insert(task).is_some() {
        return None;
    }
    let quoted: Vec<String> = quoted_segments(&request)
        .iter()
        .map(String::as_str)
        .map(super::positional_edit::unescape_prose_newlines)
        .collect();
    // Lines under the request (G22) replace the line as its siblings, unless
    // they were fenced or quoted.
    let block =
        super::positional_edit::introduced_block(task).filter(|block| block.text == replacement);
    // Listed lines (`the three lines 'a', 'b' and 'c'`) are quoted one by one (G80).
    let listed = !quoted.contains(&original);
    if (listed
        && !original
            .split('\n')
            .all(|line| quoted.iter().any(|text| text == line)))
        || (block.is_none() && !quoted.contains(&replacement))
        || original.is_empty()
        || original == replacement
    {
        return None;
    }
    Some(ComputedChange {
        target,
        intent: "coding_text_replaced",
        // Listed lines are named one by one, not as one span holding line breaks.
        slots: vec![("{old}", original.clone()), ("{new}", replacement.clone())],
        computation: Computation::LineReplacement {
            listed,
            old: original,
            new: replacement,
            context: context.map(|(_, _, text)| text),
            rebase: block.is_some_and(|block| !block.verbatim),
        },
    })
}

/// The smallest unique changed run of lines, or the lines from the context's
/// line through the change.
///
/// When the changed run repeats, the run is widened up to the context's line:
/// the context occurs once, so the widened run does not (mirrors
/// `contextLinesEdit`).
fn context_lines_edit(
    source: &str,
    updated: &str,
    context: Option<&str>,
) -> Option<(String, String)> {
    let compact = changed_lines_edit(source, updated);
    let Some(context) = context.filter(|_| compact.is_none()) else {
        return compact;
    };
    let mut found = source.match_indices(context).map(|(at, _)| at);
    let (Some(at), None) = (found.next(), found.next()) else {
        return None;
    };
    let start = source[..at].rfind('\n').map_or(0, |newline| newline + 1);
    let suffix = source[start..]
        .bytes()
        .rev()
        .zip(updated[start..].bytes().rev())
        .take_while(|(left, right)| left == right)
        .count();
    let end = source[source.len() - suffix..]
        .find('\n')
        .map_or(source.len(), |newline| source.len() - suffix + newline);
    Some((
        source[start..end].to_owned(),
        updated[start..updated.len() - (source.len() - end)].to_owned(),
    ))
}

impl ComputedChange {
    /// The seeded answer when the text a replace or removal names is gone.
    fn absent_text_answer(&self, task: &str, source: &str) -> Option<String> {
        if !matches!(self.intent, "coding_text_replaced" | "coding_text_remove") {
            return None;
        }
        let slot = |name: &str| {
            self.slots
                .iter()
                .find(|(key, _)| *key == name)
                .map(|(_, value)| value.as_str())
        };
        super::replace_list::absent_text_answer(
            task,
            &self.target,
            source,
            slot("{old}")?,
            slot("{new}"),
        )
    }

    /// The file after the change, or `None` when it cannot apply.
    fn compute(&self, source: &str, missing: bool) -> Option<String> {
        match &self.computation {
            Computation::EndInsertion {
                text,
                at_end,
                indentation,
            } => Some(inserted_at_end(
                source,
                &appended_block(source, text, indentation.as_deref()),
                *at_end,
            )),
            Computation::Removal { text } => {
                (!missing).then(|| removed_literal(source, text)).flatten()
            }
            Computation::LineRemoval { text, containing } => (!missing)
                .then(|| removed_lines(source, text, *containing))
                .flatten(),
            Computation::Setting { key, value, held } => (!missing)
                .then(|| {
                    super::workspace_setting::assigned_setting(
                        source,
                        key,
                        value,
                        &self.target,
                        held.as_deref(),
                    )
                })
                .flatten(),
            Computation::LineReplacement {
                old,
                new,
                context,
                rebase,
                ..
            } => (!missing)
                .then(|| {
                    let new = if *rebase {
                        super::positional_edit::rebased_block(new, line_indentation(source, old))
                    } else {
                        new.clone()
                    };
                    super::workspace_setting::replaced_lines(source, old, &new, context.as_deref())
                })
                .flatten(),
            Computation::TypoFix { word, correction } => (!missing)
                .then(|| {
                    execute_scoped_workspace_rewrite(source, word, correction, RewriteScope::Word)
                        .ok()
                        .map(|execution| execution.output)
                })
                .flatten(),
            Computation::DeclarationRemoval { names } => (!missing)
                .then(|| removed_declarations(source, names).map(|(updated, _)| updated))
                .flatten(),
            Computation::Line(operation) => (!missing).then(|| operation.compute(source)).flatten(),
            Computation::Section {
                heading,
                text,
                at_end,
            } => (!missing)
                .then(|| {
                    super::markdown_section::inserted_in_section(source, heading, text, *at_end)
                })
                .flatten()
                .map(|(updated, _)| updated),
            Computation::ReplaceList { pairs } => (!missing)
                .then(|| super::replace_list::replaced_in_order(source, pairs))
                .flatten(),
        }
    }

    /// Whether the request states the change's whole extent (named
    /// declarations, a numbered range), so it may remove most of a file.
    const fn bounded(&self) -> bool {
        match &self.computation {
            Computation::DeclarationRemoval { .. } => true,
            Computation::Line(operation) => operation.bounded(),
            _ => false,
        }
    }

    /// The smallest unique edit carrying the change, when there is one.
    fn edit(&self, source: &str, updated: &str) -> Option<(String, String)> {
        match &self.computation {
            Computation::EndInsertion { .. } if source.is_empty() => None,
            Computation::EndInsertion { at_end, .. } => compact_end_edit(source, updated, *at_end),
            Computation::LineReplacement { context, .. } => {
                context_lines_edit(source, updated, context.as_deref())
            }
            Computation::Removal { .. }
            | Computation::LineRemoval { .. }
            | Computation::Setting { .. }
            | Computation::TypoFix { .. }
            | Computation::DeclarationRemoval { .. }
            | Computation::Line(_)
            | Computation::Section { .. }
            | Computation::ReplaceList { .. } => changed_lines_edit(source, updated),
        }
    }
}

/// The file after the insertion; a file without a final newline keeps none.
/// Lines under an append request, at the indentation they were given.
///
/// Only when the file already has lines indented exactly so (a `.lino` table
/// appended among its siblings); else at the file's top level, since the
/// indentation of lines written under a request is otherwise only its layout
/// (PR #1188 G16).
fn appended_block(source: &str, text: &str, indentation: Option<&str>) -> String {
    match indentation {
        Some(indentation) if super::positional_edit::indents_lines_at(source, indentation) => {
            super::positional_edit::rebased_block(text, indentation)
        }
        _ => text.to_owned(),
    }
}

/// The indentation of the first line that is `text` but for its indentation.
fn line_indentation<'a>(source: &'a str, text: &str) -> &'a str {
    source
        .split('\n')
        .find(|line| line.trim() == text.trim())
        .map_or("", super::positional_edit::leading_indentation)
}

fn inserted_at_end(source: &str, text: &str, at_end: bool) -> String {
    if source.is_empty() {
        [text, "\n"].concat()
    } else if at_end && source.ends_with('\n') {
        [source, text, "\n"].concat()
    } else if at_end {
        [source, "\n", text].concat()
    } else {
        [text, "\n", source].concat()
    }
}

/// The smallest unique run of whole lines at the insertion end, and what it
/// becomes, so the edit tool carries the change rather than the whole file.
fn compact_end_edit(source: &str, updated: &str, at_end: bool) -> Option<(String, String)> {
    let starts = source
        .match_indices('\n')
        .map(|(index, _)| index + 1)
        .filter(|start| *start < source.len());
    let cuts: Vec<usize> = if at_end {
        std::iter::once(0).chain(starts).rev().collect()
    } else {
        starts.chain(std::iter::once(source.len())).collect()
    };
    for cut in cuts {
        let anchor = if at_end {
            &source[cut..]
        } else {
            &source[..cut]
        };
        if anchor.trim().is_empty() {
            continue;
        }
        if anchor.len() > MAX_ANCHOR_BYTES {
            break;
        }
        if source.matches(anchor).count() != 1 {
            continue;
        }
        let replacement = if at_end {
            &updated[cut..]
        } else {
            &updated[..updated.len() - (source.len() - cut)]
        };
        return Some((anchor.to_owned(), replacement.to_owned()));
    }
    None
}

impl ComputedChange {
    /// The seed sentence that states the change made to `source`: lines that
    /// only contained the payload are reported as lines, with their count;
    /// every other change keeps its own intent and slots.
    fn reported(&self, source: &str) -> (&'static str, Vec<(&'static str, String)>) {
        if let Computation::LineRemoval { text, containing } = &self.computation {
            let lines: Vec<&str> = source.split_inclusive('\n').map(bare_line).collect();
            let removed: Vec<&str> = removed_line_indices(source, text, *containing)
                .into_iter()
                .map(|index| lines[index])
                .collect();
            if removed.iter().any(|line| line != text) {
                return (
                    "line",
                    vec![
                        ("{old}", text.clone()),
                        ("{count}", removed.len().to_string()),
                    ],
                );
            }
        }
        if let Computation::Section {
            heading,
            text,
            at_end,
        } = &self.computation
            && let Some((_, follows)) =
                super::markdown_section::inserted_in_section(source, heading, text, *at_end)
        {
            return (
                self.intent,
                vec![("{new}", text.clone()), ("{anchor}", follows)],
            );
        }
        if let Computation::DeclarationRemoval { names } = &self.computation
            && let Some((_, declared)) = removed_declarations(source, names)
        {
            return (self.intent, vec![("{old}", declared.join("`, `"))]);
        }
        if let Computation::Line(operation) = &self.computation
            && let Some(reported) = operation.reported(source)
        {
            return reported;
        }
        (self.intent, self.slots.clone())
    }

    /// Preserve removed names and lines as explicit list values for the summary.
    fn reported_values(&self, source: &str) -> Option<Vec<String>> {
        match &self.computation {
            Computation::DeclarationRemoval { names } => {
                removed_declarations(source, names).map(|(_, values)| values)
            }
            Computation::LineReplacement {
                old, listed: true, ..
            } => Some(old.split('\n').map(str::to_owned).collect()),
            Computation::Line(operation) => operation.reported_values(source),
            _ => None,
        }
    }
}

/// Read, compute, edit (or write), check the digest, state the change.
pub(super) fn plan_computed_change_step(
    task: &str,
    current_turn: &[ChatMessage],
    tool_names: &[&str],
    change: &ComputedChange,
    result: &mut Option<FinalResult>,
) -> Option<AgenticPlan> {
    let target = change.target.as_str();
    let Some(read) = result_for_path(current_turn, Capability::Read, target, None) else {
        let tool = tool_for(tool_names, Capability::Read)?;
        return Some(plan_one(tool, read_arguments(target)));
    };
    // A read that came back as the client's file block is the file, whatever
    // its text says: a ledger that quotes error lines is not a missing file.
    let missing = super::code_artifact::source_from_agent_read_result(&read).is_none()
        && super::tool_result::failure_message(&read, false, true).is_some();
    let source = if missing {
        String::new()
    } else {
        source_from_read_result(&read)
    };
    if let Some(answer) = super::edit_scope::scoped_decline(task, target, &source) {
        return Some(AgenticPlan::Final(answer));
    }
    let Some(updated) = change
        .compute(&source, missing)
        .filter(|updated| *updated != source)
    else {
        // Text the change names that the file no longer holds is the answer (G87).
        let absent = if missing {
            None
        } else {
            change.absent_text_answer(task, &source)
        };
        return Some(AgenticPlan::Final(match absent {
            Some(answer) => answer,
            None => render_seeded_outcome("coding_workspace_verification_failed", task, target)?,
        }));
    };
    // A change that would drop most of the file is refused unless its request
    // states that extent (PR #1188 T29).
    if !change.bounded() && drops_most_of_file(&source, &updated) {
        return Some(AgenticPlan::Final(render_seeded_outcome(
            "coding_workspace_fragment_refused",
            task,
            target,
        )?));
    }
    let (intent, reported) = change.reported(&source);
    let slots: Vec<(&str, &str)> = reported
        .iter()
        .map(|(slot, value)| (*slot, value.as_str()))
        .collect();
    let values = change.reported_values(&source);
    let list_slots: Vec<(&str, &[String])> = values
        .as_deref()
        .map(|values| vec![(concat!("{", "old", "}"), values)])
        .unwrap_or_default();
    let verified = VerifiedChange {
        target,
        expected: &updated,
        intent,
        slots: &slots,
        list_slots: &list_slots,
    };
    if let Some((old, new)) = change.edit(&source, &updated)
        && let Some(tool) = tool_for(tool_names, Capability::Edit)
    {
        if result_for_edit(current_turn, target, &old, &new).is_none() {
            return Some(plan_one(tool, edit_arguments(target, &old, &new)));
        }
        return plan_digest_verification(task, current_turn, tool_names, &verified, result);
    }
    if result_for_path(current_turn, Capability::Write, target, Some(&updated)).is_none() {
        let tool = tool_for(tool_names, Capability::Write)?;
        return Some(plan_one(tool, write_arguments(target, &updated)));
    }
    plan_digest_verification(task, current_turn, tool_names, &verified, result)
}

/// `Append the line third to notes.txt`: no quoted text, one path, and the
/// seeded `file_edit_line_lead`; the line is the words after the lead up to
/// the last destination cue before the path (`go to bed to notes.txt` keeps
/// `go to bed`). A request without a lead is declined, never guessed.
fn line_payload_and_path(task: &str) -> Option<(String, String)> {
    if !quoted_segment_spans(task).is_empty() {
        return None;
    }
    let tokens = tokens(task);
    let paths: Vec<(usize, &str)> = tokens
        .iter()
        .enumerate()
        .map(|(index, token)| (index, clean_path_token(token.text)))
        .filter(|(_, path)| looks_like_file_path(path) && safe_relative_path(path))
        .collect();
    let (path_index, target) = *paths.first()?;
    if paths.iter().any(|(_, path)| *path != target) {
        return None;
    }
    let mut leads: Vec<Vec<String>> = seed::lexicon()
        .words_for_role("file_edit_line_lead")
        .iter()
        .map(|lead| {
            lead.to_lowercase()
                .split_whitespace()
                .map(str::to_owned)
                .collect::<Vec<_>>()
        })
        .filter(|words| !words.is_empty())
        .collect();
    leads.sort_by_key(|words| std::cmp::Reverse(words.len()));
    let lead_end = (0..path_index).find_map(|index| {
        leads
            .iter()
            .find(|words| {
                words.iter().enumerate().all(|(offset, word)| {
                    index + offset < path_index
                        && clean_cue_token(tokens[index + offset].text) == *word
                })
            })
            .map(|words| index + words.len())
    })?;
    let destinations = bare_surfaces("file_write_destination_cue");
    let end = (lead_end..path_index)
        .rev()
        .find(|index| destinations.contains(&clean_cue_token(tokens[*index].text)))?;
    if end <= lead_end {
        return None;
    }
    Some((
        target.to_owned(),
        task[tokens[lead_end].start..tokens[end - 1].end].to_owned(),
    ))
}

/// The one path a colon-ended request line names, with nothing else quoted
/// (mirrors `blockPayloadAndPath`).
fn block_target(head: &str) -> Option<String> {
    let mut paths: Vec<&str> = super::positional_edit::unquoted_path_tokens(head)
        .iter()
        .map(|token| clean_path_token(token.text))
        .filter(|path| looks_like_file_path(path) && safe_relative_path(path))
        .collect();
    paths.sort_unstable();
    paths.dedup();
    let [path] = paths.as_slice() else {
        return None;
    };
    quoted_segment_spans(head)
        .iter()
        .all(|segment| segment.text == *path)
        .then(|| (*path).to_owned())
}

/// The seeded `file_edit_blank_line` with one named path and no quoted text:
/// the payload is the empty string (mirrors `blankLineAndPath`).
fn blank_line_and_path(task: &str) -> Option<(String, String)> {
    if !quoted_segment_spans(task).is_empty() || !mentions("file_edit_blank_line", task) {
        return None;
    }
    let mut paths: Vec<String> = super::positional_edit::unquoted_path_tokens(task)
        .iter()
        .map(|token| clean_path_token(token.text).to_owned())
        .filter(|path| looks_like_file_path(path) && safe_relative_path(path))
        .collect();
    paths.sort();
    paths.dedup();
    match paths.as_slice() {
        [path] => Some((path.clone(), String::new())),
        _ => None,
    }
}

changes.expected:
//! Workspace changes whose new bytes are computed from the file they change
//! (PR #1188 dogfooding): text added at one end of a file, quoted text
//! removed from it, a configuration setting assigned a new value, a named
//! function removed whole.
//!
//! Each is read → compute → smallest unique edit (or the whole file) → digest
//! check → the seeded sentence that states the change, the same state machine
//! [`super::workspace_change`] runs for grounded rewrites. Before these, an
//! append (`Append the line 'third line' to notes.txt.`) reached the
//! general-change fallback and was written as the *whole* file.

use super::code_artifact::source_from_read_result;
use super::code_task::render_seeded_outcome;
use super::final_result::FinalResult;
use super::general_planner::compose_edit_request;
use super::intent_router::edit_arguments;
use super::line_removal::{
    bare_line, removed_declarations, removed_line_indices, removed_lines, removed_literal,
};
use super::planner::{AgenticPlan, Capability, plan_one, tool_for, write_arguments};
use super::workspace_change::{
    VerifiedChange, changed_lines_edit, identifier_tokens, plan_digest_verification,
    read_arguments, result_for_edit, result_for_path,
};
use super::workspace_line_operation::{
    LineOperation, drops_most_of_file, grounded_line_operation, named_target_and_payloads,
};
use super::write_request::{
    bare_surfaces, clean_cue_token, clean_path_token, looks_like_file_path, safe_relative_path,
    tokens,
};
use crate::normal_markov::{quoted_segment_spans, quoted_segments};
use crate::protocol::ChatMessage;
use crate::seed;
use crate::workspace_change_learning::{
    RewriteScope, execute_scoped_workspace_rewrite, is_identifier_word,
};

const MAX_ANCHOR_BYTES: usize = 4096;

/// How a computed change derives the file's new bytes.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(super) enum Computation {
    /// Quoted text placed as the last (`at_end`) or the first line; lines
    /// given under the request keep their shared `indentation` when the file
    /// has lines indented exactly so (PR #1188 G16).
    EndInsertion {
        text: String,
        at_end: bool,
        indentation: Option<String>,
    },
    /// Every line that is exactly `text`, else its one in-line occurrence.
    Removal { text: String },
    /// Whole lines (the request names a line): see `removed_line_indices`.
    LineRemoval { text: String, containing: bool },
    /// The one line assigning `key` (holding `held`, when stated) gets
    /// `value`, in the file's own quoting.
    Setting {
        key: String,
        value: String,
        held: Option<String>,
    },
    /// Every line that is `old` becomes `new` (the request names a line), or
    /// only the first one after `context`.
    LineReplacement {
        listed: bool,
        old: String,
        new: String,
        context: Option<String>,
        rebase: bool,
    },
    /// Every whole-word `word` becomes its discovered `correction`.
    TypoFix { word: String, correction: String },
    /// The functions the file declares under these names go whole, with the
    /// comment and attribute lines directly above them.
    DeclarationRemoval { names: Vec<String> },
    /// A whole-line operation: numbered, adjacent, moved or swapped lines.
    Line(LineOperation),
    /// `text` placed at one end of the Markdown section under `heading`
    /// (PR #1188 G35).
    Section {
        heading: String,
        text: String,
        at_end: bool,
    },
    /// Each `(old, new)` pair replaced everywhere, in order (PR #1188 G82).
    ReplaceList { pairs: Vec<(String, String)> },
}

/// A computed change: the file, how its bytes are computed, and the seed
/// sentence (intent and slots) that states it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(super) struct ComputedChange {
    pub(super) target: String,
    pub(super) computation: Computation,
    pub(super) intent: &'static str,
    pub(super) slots: Vec<(&'static str, String)>,
}

/// The first computed change `task` asks for, if any.
pub(super) fn grounded_computed_change(task: &str) -> Option<ComputedChange> {
    grounded_end_insertion(task)
        .or_else(|| grounded_removal(task))
        .or_else(|| grounded_declaration_removal(task))
        .or_else(|| grounded_line_replacement(task))
        .or_else(|| grounded_setting(task))
        .or_else(|| grounded_typo_fix(task))
}

/// `Fix the typo 'smal' in README.md`: the seeded `typo_fix_lead` with one
/// quoted word and one path, and no stated correction. The correction is
/// discovered ([`super::spelling::corrected_spelling`]), and the change is the
/// word-scoped replacement a stated correction would have made.
fn grounded_typo_fix(task: &str) -> Option<ComputedChange> {
    if !mentions("typo_fix_lead", task) {
        return None;
    }
    let (target, word) = quoted_payload_and_path(task)?;
    if !is_identifier_word(&word) {
        return None;
    }
    let correction = super::spelling::corrected_spelling(&word)?;
    Some(ComputedChange {
        target,
        intent: "coding_text_replaced",
        slots: vec![("{old}", word.clone()), ("{new}", correction.clone())],
        computation: Computation::TypoFix { word, correction },
    })
}

fn mentions(role: &str, task: &str) -> bool {
    seed::lexicon().mentions_role(role, &sentence_words(task))
}

/// The marks that end a sentence or a clause.
const SENTENCE_MARKS: [char; 11] = [
    '.', '!', '?', ';', ':', ',', '\u{0964}', '\u{0965}', '\u{3002}', '\u{ff01}', '\u{ff1f}',
];

/// The lowered request with the marks that end a sentence or clause set off
/// as spaces, so a verb that closes its sentence (`… पंक्ति हटाओ।`, `…
/// удали.`) is still a whole word. A dot inside a token (`t.md`) is not
/// followed by a space and stays.
pub(super) fn sentence_words(task: &str) -> String {
    let lowered = task.to_lowercase();
    let characters: Vec<char> = lowered.chars().collect();
    let mut out = String::with_capacity(lowered.len());
    let mut index = 0;
    while index < characters.len() {
        let mut end = index;
        while end < characters.len() && SENTENCE_MARKS.contains(&characters[end]) {
            end += 1;
        }
        if end > index && characters.get(end).is_none_or(|next| next.is_whitespace()) {
            out.push(' ');
            index = end;
        } else {
            out.push(characters[index]);
            index += 1;
        }
    }
    out
}

/// Whether the request is about text inside a file: it quotes a payload that
/// is not a path, or names a line (the seeded `line` meaning) or another unit
/// of text (`file_text_unit`: word, phrase, occurrence, text, in every
/// registered language) outside its quotes. A destructive shell intent never
/// reads such a request as deleting the file (PR #1188).
pub(super) fn edits_inside_a_file(prompt: &str) -> bool {
    if quoted_segment_spans(prompt)
        .iter()
        .map(|segment| segment.text.trim())
        .any(|text| !text.is_empty() && !super::shell_command::looks_like_a_path(text))
    {
        return true;
    }
    let outside = crate::engine::normalize_prompt(
        &crate::solver_handlers::text_outside_quoted_segments(&without_path_words(prompt)),
    )
    .to_lowercase();
    seed::lexicon()
        .meaning("line")
        .is_some_and(|meaning| meaning.evidenced_in(&outside))
        || seed::lexicon().mentions_role("file_text_unit", &outside)
}

/// Whether the request names a line outside its quotes: the seeded `line`
/// meaning (`the line containing '…'`, `lines`, `строку`, `पंक्ति`, `的行`).
pub(super) fn names_line(task: &str) -> bool {
    // A path's own words are no line: `x-line.lino` names a file (PR #1188 G83).
    seed::lexicon()
        .meaning("line")
        .is_some_and(|meaning| meaning.evidenced_in(&outside_quotes(&without_path_words(task))))
}

/// `task` with every unquoted path token blanked.
///
/// A path's own words (`x-line.lino`, `line-budget.lino`) never read as the
/// words of the request (PR #1188 G83; mirrors `withoutPathWords`).
pub(super) fn without_path_words(task: &str) -> String {
    let segments = quoted_segment_spans(task);
    let mut out = task.to_owned();
    for token in super::write_request::tokens(task).iter().rev() {
        if segments
            .iter()
            .any(|segment| token.start < segment.end && token.end > segment.start)
        {
            continue;
        }
        let path = super::write_request::clean_path_token(token.text);
        if super::write_request::looks_like_file_path(path) {
            out.replace_range(token.start..token.end, &" ".repeat(token.end - token.start));
        }
    }
    out
}

/// The lowered request outside its quotes.
fn outside_quotes(task: &str) -> String {
    let outside = crate::solver_handlers::text_outside_quoted_segments(task);
    crate::engine::normalize_prompt(&outside).to_lowercase()
}

/// The one workspace path a request names and its one quoted segment that is
/// not that path. An unquoted path outranks a quoted one, which is then the
/// payload (PR #1188 T35).
fn quoted_payload_and_path(task: &str) -> Option<(String, String)> {
    let (target, payloads) = named_target_and_payloads(task)?;
    let [payload] = payloads.as_slice() else {
        return None;
    };
    Some((target, payload.clone()))
}

/// A whole-line operation (numbered, adjacent, moved or swapped lines) as a
/// computed change. It is read before a rewrite: `move 'x' after 'y'` is not
/// an insertion (PR #1188).
/// Several quoted replacements in one file, asked in one sentence, as one
/// computed change (PR #1188 G82; mirrors `groundedReplaceList`).
pub(super) fn grounded_replace_list(task: &str) -> Option<ComputedChange> {
    let (target, pairs) = super::replace_list::replace_list(task)?;
    let listed: Vec<String> = pairs
        .iter()
        .map(|(old, new)| format!("`{old}` → `{new}`"))
        .collect();
    Some(ComputedChange {
        target,
        intent: "coding_texts_replaced",
        slots: vec![
            (concat!("{", "pairs", "}"), listed.join(", ")),
            (concat!("{", "count", "}"), pairs.len().to_string()),
        ],
        computation: Computation::ReplaceList { pairs },
    })
}

pub(super) fn grounded_line_change(task: &str) -> Option<ComputedChange> {
    let change = grounded_line_operation(task)?;
    Some(ComputedChange {
        target: change.target,
        computation: Computation::Line(change.operation),
        intent: change.intent,
        slots: change.slots,
    })
}

/// `Append 'x' to notes.txt`, `Prepend "x" to a.md`: positioned by the seeded
/// `file_edit_position_end` / `file_edit_position_start` meanings.
pub(super) fn grounded_end_insertion(task: &str) -> Option<ComputedChange> {
    // `Append these lines to f:` followed by lines: the first line is the
    // request and the lines under it are the text added, verbatim (PR #1188).
    let block = super::positional_edit::introduced_block(task);
    // Position cues are read outside the quoted payload: a line saying "at the
    // start of x" is text being appended (PR #1188 G64).
    let cues = block
        .as_ref()
        .map_or_else(|| outside_quotes(task), |block| sentence_words(block.head));
    let lexicon = seed::lexicon();
    let at_end = lexicon.mentions_role("file_edit_position_end", &cues);
    if at_end == lexicon.mentions_role("file_edit_position_start", &cues) {
        return None;
    }
    // `… at the end of the section '## Usage' in README.md` (PR #1188 G35).
    if block.is_none()
        && let Some(section) = super::markdown_section::section_scope(task, &outside_quotes(task))
    {
        let text = super::positional_edit::unescape_prose_newlines(&section.text);
        return Some(ComputedChange {
            target: section.target,
            intent: "file_edit_position_after",
            slots: vec![
                ("{new}", text.clone()),
                ("{anchor}", section.heading.clone()),
            ],
            computation: Computation::Section {
                heading: section.heading,
                text,
                at_end,
            },
        });
    }
    let (target, text, indentation) = if let Some(block) = block {
        let indentation = (!block.verbatim).then(|| block.indentation.to_owned());
        (block_target(block.head)?, block.text, indentation)
    } else if let Some((target, text)) = quoted_lines_and_path(task) {
        (target, text, None)
    } else {
        let (target, text) = quoted_payload_and_path(task)
            .or_else(|| blank_line_and_path(task))
            .or_else(|| line_payload_and_path(task))?;
        (
            target,
            super::positional_edit::unescape_prose_newlines(&text),
            None,
        )
    };
    Some(ComputedChange {
        target,
        // An empty line has no text to quote back; it is stated in its own words.
        intent: if text.is_empty() {
            "file_edit_blank_line"
        } else if at_end {
            "file_edit_position_end"
        } else {
            "file_edit_position_start"
        },
        slots: vec![("{new}", text.clone())],
        computation: Computation::EndInsertion {
            text,
            at_end,
            indentation,
        },
    })
}

/// Several quoted literals, joined only by seeded joiners and commas, are the
/// lines added, each its own line, as written (PR #1188 G53, G54).
fn quoted_lines_and_path(task: &str) -> Option<(String, String)> {
    let (target, payloads) = named_target_and_payloads(task)?;
    if payloads.len() < 2 {
        return None;
    }
    let text = super::positional_edit::joined_literal_lines(task, &target)?;
    Some((target, text))
}

/// `Delete the line 'x' from notes.txt`: the seeded `coding_text_remove_action`
/// with one quoted payload and one path, and no add action alongside it.
fn grounded_removal(task: &str) -> Option<ComputedChange> {
    if !mentions("coding_text_remove_action", task) || mentions("coding_member_add_action", task) {
        return None;
    }
    let (target, text) = quoted_payload_and_path(task)?;
    // A request that names a line removes whole lines, never only the
    // payload inside one (PR #1188 G60).
    let computation = if names_line(task) {
        let containing =
            seed::lexicon().mentions_role("line_containment_cue", &outside_quotes(task));
        Computation::LineRemoval {
            text: text.clone(),
            containing,
        }
    } else {
        Computation::Removal { text: text.clone() }
    };
    Some(ComputedChange {
        target,
        intent: "coding_text_remove",
        slots: vec![("{old}", text)],
        computation,
    })
}

/// `Delete the functions a and b from util.rs`: the seeded
/// `coding_text_remove_action` and `coding_declaration_noun` with no add
/// action, no quoted text and one named path. The names are the request's
/// identifiers; `removed_declarations` keeps those the file itself declares
/// as functions (mirrors `groundedDeclarationRemoval`, PR #1188 dogfooding).
fn grounded_declaration_removal(task: &str) -> Option<ComputedChange> {
    if !mentions("coding_text_remove_action", task)
        || mentions("coding_member_add_action", task)
        || !mentions("coding_declaration_noun", task)
        || !quoted_segment_spans(task).is_empty()
    {
        return None;
    }
    let mut paths: Vec<String> = super::positional_edit::unquoted_path_tokens(task)
        .iter()
        .map(|token| clean_path_token(token.text).to_owned())
        .filter(|path| looks_like_file_path(path) && safe_relative_path(path))
        .collect();
    paths.sort();
    paths.dedup();
    let [target] = paths.as_slice() else {
        return None;
    };
    let mut names: Vec<String> = Vec::new();
    for token in tokens(task) {
        if clean_path_token(token.text) == target {
            continue;
        }
        for name in identifier_tokens(token.text) {
            if !names.iter().any(|known| known == name) {
                names.push(name.to_owned());
            }
        }
    }
    if names.is_empty() {
        return None;
    }
    Some(ComputedChange {
        target: target.clone(),
        intent: "coding_text_remove",
        slots: vec![("{old}", names.join("`, `"))],
        computation: Computation::DeclarationRemoval { names },
    })
}

/// `Change the value of "debug" to true in config.json`: the seeded
/// `config_value_lead` names a setting; the edit request's old clause names its
/// key (quoted, or its last identifier) and the new clause its value.
///
/// `Change MAXIMUM_RATIO from 8 to 16 in p.rs` states the value the key holds
/// now (the seeded `file_edit_old_lead_cue`): the line assigning the key that
/// value is the one changed, and a key assigned nowhere leaves the stated
/// value itself, when it occurs once as a word (PR #1188 G2).
fn grounded_setting(task: &str) -> Option<ComputedChange> {
    let (target, old_clause, value) = compose_edit_request(task)?;
    let stated = super::workspace_setting::stated_old_value(&old_clause);
    if stated.is_none() && !mentions("config_value_lead", task) {
        return None;
    }
    // `set the contents of note.txt to hello` writes the file; its contents are
    // not a key (PR #1188 G68, issue #745).
    if stated.is_none() && mentions("file_contents_source_cue", task) {
        return None;
    }
    let key_clause = stated
        .as_ref()
        .map_or(old_clause.as_str(), |(key, _)| key.as_str());
    let quoted = quoted_segments(key_clause);
    let key = match quoted.as_slice() {
        [key] => key.clone(),
        _ => identifier_tokens(key_clause).next_back()?.to_owned(),
    };
    let value = value.trim().to_owned();
    if value.is_empty() {
        return None;
    }
    Some(ComputedChange {
        target,
        intent: "setting",
        slots: vec![("{old}", key.clone()), ("{new}", value.clone())],
        computation: Computation::Setting {
            key,
            value,
            held: stated.map(|(_, held)| held),
        },
    })
}

/// `Replace the line 'x' with 'y' in f`: the seeded `line` meaning outside
/// the quotes, both clauses quoted. A line replacement never touches text
/// inside a longer line (T32: `text pays` became `text "pay"s`). With a seeded
/// anchor context (`the line 'x' that follows the line 'z'`), the first such
/// line after `z` is the one replaced (T62).
fn grounded_line_replacement(task: &str) -> Option<ComputedChange> {
    if !names_line(task)
        || seed::lexicon().mentions_role(
            seed::ROLE_CODING_IDENTIFIER_RENAME_ACTION,
            &task.to_lowercase(),
        )
    {
        return None;
    }
    let context = super::positional_edit::anchor_context(task);
    let request = context.as_ref().map_or_else(
        || task.to_owned(),
        |(start, end, _)| [&task[..*start], " ", &task[*end..]].concat(),
    );
    let (target, original, replacement) = compose_edit_request(&request)?;
    if super::positional_edit::compose_positional_insert(task).is_some() {
        return None;
    }
    let quoted: Vec<String> = quoted_segments(&request)
        .iter()
        .map(String::as_str)
        .map(super::positional_edit::unescape_prose_newlines)
        .collect();
    // Lines under the request (G22) replace the line as its siblings, unless
    // they were fenced or quoted.
    let block =
        super::positional_edit::introduced_block(task).filter(|block| block.text == replacement);
    // Listed lines (`the three lines 'a', 'b' and 'c'`) are quoted one by one (G80).
    let listed = !quoted.contains(&original);
    if (listed
        && !original
            .split('\n')
            .all(|line| quoted.iter().any(|text| text == line)))
        || (block.is_none() && !quoted.contains(&replacement))
        || original.is_empty()
        || original == replacement
    {
        return None;
    }
    Some(ComputedChange {
        target,
        intent: "coding_text_replaced",
        // Listed lines are named one by one, not as one span holding line breaks.
        slots: vec![("{old}", original.clone()), ("{new}", replacement.clone())],
        computation: Computation::LineReplacement {
            listed,
            old: original,
            new: replacement,
            context: context.map(|(_, _, text)| text),
            rebase: block.is_some_and(|block| !block.verbatim),
        },
    })
}

/// The smallest unique changed run of lines, or the lines from the context's
/// line through the change.
///
/// When the changed run repeats, the run is widened up to the context's line:
/// the context occurs once, so the widened run does not (mirrors
/// `contextLinesEdit`).
fn context_lines_edit(
    source: &str,
    updated: &str,
    context: Option<&str>,
) -> Option<(String, String)> {
    let compact = changed_lines_edit(source, updated);
    let Some(context) = context.filter(|_| compact.is_none()) else {
        return compact;
    };
    let mut found = source.match_indices(context).map(|(at, _)| at);
    let (Some(at), None) = (found.next(), found.next()) else {
        return None;
    };
    let start = source[..at].rfind('\n').map_or(0, |newline| newline + 1);
    let suffix = source[start..]
        .bytes()
        .rev()
        .zip(updated[start..].bytes().rev())
        .take_while(|(left, right)| left == right)
        .count();
    let end = source[source.len() - suffix..]
        .find('\n')
        .map_or(source.len(), |newline| source.len() - suffix + newline);
    Some((
        source[start..end].to_owned(),
        updated[start..updated.len() - (source.len() - end)].to_owned(),
    ))
}

impl ComputedChange {
    /// The seeded answer when the text a replace or removal names is gone.
    fn absent_text_answer(&self, task: &str, source: &str) -> Option<String> {
        if !matches!(self.intent, "coding_text_replaced" | "coding_text_remove") {
            return None;
        }
        let slot = |name: &str| {
            self.slots
                .iter()
                .find(|(key, _)| *key == name)
                .map(|(_, value)| value.as_str())
        };
        super::replace_list::absent_text_answer(
            task,
            &self.target,
            source,
            slot("{old}")?,
            slot("{new}"),
        )
    }

    /// The file after the change, or `None` when it cannot apply.
    fn compute(&self, source: &str, missing: bool) -> Option<String> {
        match &self.computation {
            Computation::EndInsertion {
                text,
                at_end,
                indentation,
            } => Some(inserted_at_end(
                source,
                &appended_block(source, text, indentation.as_deref()),
                *at_end,
            )),
            Computation::Removal { text } => {
                (!missing).then(|| removed_literal(source, text)).flatten()
            }
            Computation::LineRemoval { text, containing } => (!missing)
                .then(|| removed_lines(source, text, *containing))
                .flatten(),
            Computation::Setting { key, value, held } => (!missing)
                .then(|| {
                    super::workspace_setting::assigned_setting(
                        source,
                        key,
                        value,
                        &self.target,
                        held.as_deref(),
                    )
                })
                .flatten(),
            Computation::LineReplacement {
                old,
                new,
                context,
                rebase,
                ..
            } => (!missing)
                .then(|| {
                    let new = if *rebase {
                        super::positional_edit::rebased_block(new, line_indentation(source, old))
                    } else {
                        new.clone()
                    };
                    super::workspace_setting::replaced_lines(source, old, &new, context.as_deref())
                })
                .flatten(),
            Computation::TypoFix { word, correction } => (!missing)
                .then(|| {
                    execute_scoped_workspace_rewrite(source, word, correction, RewriteScope::Word)
                        .ok()
                        .map(|execution| execution.output)
                })
                .flatten(),
            Computation::DeclarationRemoval { names } => (!missing)
                .then(|| removed_declarations(source, names).map(|(updated, _)| updated))
                .flatten(),
            Computation::Line(operation) => (!missing).then(|| operation.compute(source)).flatten(),
            Computation::Section {
                heading,
                text,
                at_end,
            } => (!missing)
                .then(|| {
                    super::markdown_section::inserted_in_section(source, heading, text, *at_end)
                })
                .flatten()
                .map(|(updated, _)| updated),
            Computation::ReplaceList { pairs } => (!missing)
                .then(|| super::replace_list::replaced_in_order(source, pairs))
                .flatten(),
        }
    }

    /// Whether the request states the change's whole extent (named
    /// declarations, a numbered range), so it may remove most of a file.
    const fn bounded(&self) -> bool {
        match &self.computation {
            Computation::DeclarationRemoval { .. } => true,
            Computation::Line(operation) => operation.bounded(),
            _ => false,
        }
    }

    /// The smallest unique edit carrying the change, when there is one.
    fn edit(&self, source: &str, updated: &str) -> Option<(String, String)> {
        match &self.computation {
            Computation::EndInsertion { .. } if source.is_empty() => None,
            Computation::EndInsertion { at_end, .. } => compact_end_edit(source, updated, *at_end),
            Computation::LineReplacement { context, .. } => {
                context_lines_edit(source, updated, context.as_deref())
            }
            Computation::Removal { .. }
            | Computation::LineRemoval { .. }
            | Computation::Setting { .. }
            | Computation::TypoFix { .. }
            | Computation::DeclarationRemoval { .. }
            | Computation::Line(_)
            | Computation::Section { .. }
            | Computation::ReplaceList { .. } => changed_lines_edit(source, updated),
        }
    }
}

/// The file after the insertion; a file without a final newline keeps none.
/// Lines under an append request, at the indentation they were given.
///
/// Only when the file already has lines indented exactly so (a `.lino` table
/// appended among its siblings); else at the file's top level, since the
/// indentation of lines written under a request is otherwise only its layout
/// (PR #1188 G16).
fn appended_block(source: &str, text: &str, indentation: Option<&str>) -> String {
    match indentation {
        Some(indentation) if super::positional_edit::indents_lines_at(source, indentation) => {
            super::positional_edit::rebased_block(text, indentation)
        }
        _ => text.to_owned(),
    }
}

/// The indentation of the first line that is `text` but for its indentation.
fn line_indentation<'a>(source: &'a str, text: &str) -> &'a str {
    source
        .split('\n')
        .find(|line| line.trim() == text.trim())
        .map_or("", super::positional_edit::leading_indentation)
}

fn inserted_at_end(source: &str, text: &str, at_end: bool) -> String {
    if source.is_empty() {
        [text, "\n"].concat()
    } else if at_end && source.ends_with('\n') {
        [source, text, "\n"].concat()
    } else if at_end {
        [source, "\n", text].concat()
    } else {
        [text, "\n", source].concat()
    }
}

/// The smallest unique run of whole lines at the insertion end, and what it
/// becomes, so the edit tool carries the change rather than the whole file.
fn compact_end_edit(source: &str, updated: &str, at_end: bool) -> Option<(String, String)> {
    let starts = source
        .match_indices('\n')
        .map(|(index, _)| index + 1)
        .filter(|start| *start < source.len());
    let cuts: Vec<usize> = if at_end {
        std::iter::once(0).chain(starts).rev().collect()
    } else {
        starts.chain(std::iter::once(source.len())).collect()
    };
    for cut in cuts {
        let anchor = if at_end {
            &source[cut..]
        } else {
            &source[..cut]
        };
        if anchor.trim().is_empty() {
            continue;
        }
        if anchor.len() > MAX_ANCHOR_BYTES {
            break;
        }
        if source.matches(anchor).count() != 1 {
            continue;
        }
        let replacement = if at_end {
            &updated[cut..]
        } else {
            &updated[..updated.len() - (source.len() - cut)]
        };
        return Some((anchor.to_owned(), replacement.to_owned()));
    }
    None
}

impl ComputedChange {
    /// The seed sentence that states the change made to `source`: lines that
    /// only contained the payload are reported as lines, with their count;
    /// every other change keeps its own intent and slots.
    fn reported(&self, source: &str) -> (&'static str, Vec<(&'static str, String)>) {
        if let Computation::LineRemoval { text, containing } = &self.computation {
            let lines: Vec<&str> = source.split_inclusive('\n').map(bare_line).collect();
            let removed: Vec<&str> = removed_line_indices(source, text, *containing)
                .into_iter()
                .map(|index| lines[index])
                .collect();
            if removed.iter().any(|line| line != text) {
                return (
                    "line",
                    vec![
                        ("{old}", text.clone()),
                        ("{count}", removed.len().to_string()),
                    ],
                );
            }
        }
        if let Computation::Section {
            heading,
            text,
            at_end,
        } = &self.computation
            && let Some((_, follows)) =
                super::markdown_section::inserted_in_section(source, heading, text, *at_end)
        {
            return (
                self.intent,
                vec![("{new}", text.clone()), ("{anchor}", follows)],
            );
        }
        if let Computation::DeclarationRemoval { names } = &self.computation
            && let Some((_, declared)) = removed_declarations(source, names)
        {
            return (self.intent, vec![("{old}", declared.join("`, `"))]);
        }
        if let Computation::Line(operation) = &self.computation
            && let Some(reported) = operation.reported(source)
        {
            return reported;
        }
        (self.intent, self.slots.clone())
    }

    /// Preserve removed names and lines as explicit list values for the summary.
    fn reported_values(&self, source: &str) -> Option<Vec<String>> {
        match &self.computation {
            Computation::DeclarationRemoval { names } => {
                removed_declarations(source, names).map(|(_, values)| values)
            }
            Computation::LineReplacement {
                old, listed: true, ..
            } => Some(old.split('\n').map(str::to_owned).collect()),
            Computation::Line(operation) => operation.reported_values(source),
            _ => None,
        }
    }
}

/// Read, compute, edit (or write), check the digest, state the change.
pub(super) fn plan_computed_change_step(
    task: &str,
    current_turn: &[ChatMessage],
    tool_names: &[&str],
    change: &ComputedChange,
    result: &mut Option<FinalResult>,
) -> Option<AgenticPlan> {
    let target = change.target.as_str();
    let Some(read) = result_for_path(current_turn, Capability::Read, target, None) else {
        let tool = tool_for(tool_names, Capability::Read)?;
        return Some(plan_one(tool, read_arguments(target)));
    };
    // A read that came back as the client's file block is the file, whatever
    // its text says: a ledger that quotes error lines is not a missing file.
    let missing = super::code_artifact::source_from_agent_read_result(&read).is_none()
        && super::tool_result::failure_message(&read, false, true).is_some();
    let source = if missing {
        String::new()
    } else {
        source_from_read_result(&read)
    };
    if let Some(answer) = super::edit_scope::scoped_decline(task, target, &source) {
        return Some(AgenticPlan::Final(answer));
    }
    let Some(updated) = change
        .compute(&source, missing)
        .filter(|updated| *updated != source)
    else {
        // Text the change names that the file no longer holds is the answer (G87).
        let absent = if missing {
            None
        } else {
            change.absent_text_answer(task, &source)
        };
        return Some(AgenticPlan::Final(match absent {
            Some(answer) => answer,
            None => render_seeded_outcome("coding_workspace_verification_failed", task, target)?,
        }));
    };
    // A change that would drop most of the file is refused unless its request
    // states that extent (PR #1188 T29).
    if !change.bounded() && drops_most_of_file(&source, &updated) {
        return Some(AgenticPlan::Final(render_seeded_outcome(
            "coding_workspace_fragment_refused",
            task,
            target,
        )?));
    }
    let (intent, reported) = change.reported(&source);
    let slots: Vec<(&str, &str)> = reported
        .iter()
        .map(|(slot, value)| (*slot, value.as_str()))
        .collect();
    let values = change.reported_values(&source);
    let list_slots: Vec<(&str, &[String])> = values
        .as_deref()
        .map(|values| vec![(concat!("{", "old", "}"), values)])
        .unwrap_or_default();
    let verified = VerifiedChange {
        target,
        expected: &updated,
        intent,
        slots: &slots,
        list_slots: &list_slots,
    };
    if let Some((old, new)) = change.edit(&source, &updated)
        && let Some(tool) = tool_for(tool_names, Capability::Edit)
    {
        if result_for_edit(current_turn, target, &old, &new).is_none() {
            return Some(plan_one(tool, edit_arguments(target, &old, &new)));
        }
        return plan_digest_verification(task, current_turn, tool_names, &verified, result);
    }
    if result_for_path(current_turn, Capability::Write, target, Some(&updated)).is_none() {
        let tool = tool_for(tool_names, Capability::Write)?;
        return Some(plan_one(tool, write_arguments(target, &updated)));
    }
    plan_digest_verification(task, current_turn, tool_names, &verified, result)
}

/// `Append the line third to notes.txt`: no quoted text, one path, and the
/// seeded `file_edit_line_lead`; the line is the words after the lead up to
/// the last destination cue before the path (`go to bed to notes.txt` keeps
/// `go to bed`). A request without a lead is declined, never guessed.
fn line_payload_and_path(task: &str) -> Option<(String, String)> {
    if !quoted_segment_spans(task).is_empty() {
        return None;
    }
    let tokens = tokens(task);
    let paths: Vec<(usize, &str)> = tokens
        .iter()
        .enumerate()
        .map(|(index, token)| (index, clean_path_token(token.text)))
        .filter(|(_, path)| looks_like_file_path(path) && safe_relative_path(path))
        .collect();
    let (path_index, target) = *paths.first()?;
    if paths.iter().any(|(_, path)| *path != target) {
        return None;
    }
    let mut leads: Vec<Vec<String>> = seed::lexicon()
        .words_for_role("file_edit_line_lead")
        .iter()
        .map(|lead| {
            lead.to_lowercase()
                .split_whitespace()
                .map(str::to_owned)
                .collect::<Vec<_>>()
        })
        .filter(|words| !words.is_empty())
        .collect();
    leads.sort_by_key(|words| std::cmp::Reverse(words.len()));
    let lead_end = (0..path_index).find_map(|index| {
        leads
            .iter()
            .find(|words| {
                words.iter().enumerate().all(|(offset, word)| {
                    index + offset < path_index
                        && clean_cue_token(tokens[index + offset].text) == *word
                })
            })
            .map(|words| index + words.len())
    })?;
    let destinations = bare_surfaces("file_write_destination_cue");
    let end = (lead_end..path_index)
        .rev()
        .find(|index| destinations.contains(&clean_cue_token(tokens[*index].text)))?;
    if end <= lead_end {
        return None;
    }
    Some((
        target.to_owned(),
        task[tokens[lead_end].start..tokens[end - 1].end].to_owned(),
    ))
}

/// The one path a colon-ended request line names, with nothing else quoted
/// (mirrors `blockPayloadAndPath`).
fn block_target(head: &str) -> Option<String> {
    let mut paths: Vec<&str> = super::positional_edit::unquoted_path_tokens(head)
        .iter()
        .map(|token| clean_path_token(token.text))
        .filter(|path| looks_like_file_path(path) && safe_relative_path(path))
        .collect();
    paths.sort_unstable();
    paths.dedup();
    let [path] = paths.as_slice() else {
        return None;
    };
    quoted_segment_spans(head)
        .iter()
        .all(|segment| segment.text == *path)
        .then(|| (*path).to_owned())
}

/// The seeded `file_edit_blank_line` with one named path and no quoted text:
/// the payload is the empty string (mirrors `blankLineAndPath`).
fn blank_line_and_path(task: &str) -> Option<(String, String)> {
    if !quoted_segment_spans(task).is_empty() || !mentions("file_edit_blank_line", task) {
        return None;
    }
    let mut paths: Vec<String> = super::positional_edit::unquoted_path_tokens(task)
        .iter()
        .map(|token| clean_path_token(token.text).to_owned())
        .filter(|path| looks_like_file_path(path) && safe_relative_path(path))
        .collect();
    paths.sort();
    paths.dedup();
    match paths.as_slice() {
        [path] => Some((path.clone(), String::new())),
        _ => None,
    }
}

