        .into_iter()
        .filter(|token| {
            !segments
                .iter()
                .any(|segment| token.start < segment.end && token.end > segment.start)
        })
        .collect();
    let cues: Vec<String> = CUE_ROLES.into_iter().flat_map(bare_surfaces).collect();
