        .iter()
        .enumerate()
        .map(|(index, token)| (index, clean_path_token(token.text).to_owned()))
        .filter(|(_, path)| is_path(path))
        .collect();
    let mut distinct: Vec<&str> = paths.iter().map(|(_, path)| path.as_str()).collect();
    distinct.sort_unstable();
    distinct.dedup();
